/* Теория первой помощи. Подключается в index.html отдельным файлом. */

var FIRSTAID_THEORY = [
['Оценка ситуации и безопасность спасателя','ПОЧЕМУ ЭТО ПЕРВЫЙ ШАГ\nМеждународные протоколы (Европейский совет по реанимации, Красный Крест) ставят оценку безопасности раньше контакта с пострадавшим — спасатель, ставший второй жертвой, не помогает, а увеличивает число пострадавших.\n\nБЫСТРЫЙ ОБЗОР ОПАСНОСТЕЙ\nНесколько секунд на осмотр: огонь, оголённые провода, утечка газа, неустойчивые конструкции, риск повторной аварии, агрессивные животные или люди — счёт идёт на секунды, но пропускать нельзя даже под давлением стресса.\n\nПРАВИЛО ТРЁХ УРОВНЕЙ БЕЗОПАСНОСТИ\nБезопасность спасателя первична, окружающих вторична, пострадавшего — затем. Недееспособный спасатель не поможет никому.\n\nСИТУАЦИИ, ТРЕБУЮЩИЕ ПЕРЕМЕЩЕНИЯ ДО ОСМОТРА\nОбщее правило не двигать пострадавшего до осмотра уступает более приоритетному правилу немедленной эвакуации при огне, риске взрыва, наезда, обрушения — риск немедленной гибели превышает риск усугубления возможной травмы позвоночника.\n\nИСПОЛЬЗОВАНИЕ СРЕДСТВ ЗАЩИТЫ\nПри наличии перчаток их использование обязательно; при отсутствии — любой барьерный материал, а при задержке, создающей больший риск, допустимо действовать голыми руками.\n\nПСИХОЛОГИЧЕСКАЯ ГОТОВНОСТЬ К ДЕЙСТВИЮ ПОД СТРЕССОМ\nОтработанный заранее алгоритм (осмотреться, оценить, действовать) снижает вероятность промедления или поспешного действия без оценки опасности.\n\nОЦЕНКА ЧИСЛА ПОСТРАДАВШИХ\nПри нескольких пострадавших сначала беглая общая оценка, чтобы не сосредоточиться на первом увиденном в ущерб более тяжёлому, но менее заметному случаю.\n\nОБРАЩЕНИЕ ЗА ПОМОЩЬЮ ОКРУЖАЮЩИХ\nАдресное обращение к конкретному человеку эффективнее общего призыва — диффузия ответственности в толпе задокументирована социальной психологией.\n\nТИПИЧНЫЕ ОШИБКИ\nНемедленный контакт без оценки обстановки; помощь в зоне сохраняющейся опасности; неадресный призыв о помощи; сосредоточение на первом пострадавшем без оценки общей картины.\n\nПРОВЕРЬ СЕБЯ\n1. Почему оценка безопасности предшествует контакту с пострадавшим?\n2. Каково правило трёх уровней приоритета безопасности?\n3. Когда допустимо переместить пострадавшего до завершения осмотра?\n4. Что делать при отсутствии перчаток и большом риске задержки?\n5. Почему адресное обращение эффективнее общего призыва?'],
['Алгоритм ABC и первичный осмотр пострадавшего','ПРОИСХОЖДЕНИЕ И НАЗНАЧЕНИЕ АЛГОРИТМА\nABC (Airway, Breathing, Circulation) — строгий порядок первичной оценки, отражающий иерархию того, что убивает быстрее: нарушение проходимости путей смерти наступает быстрее большинства кровотечений.\n\nA — ПРОХОДИМОСТЬ ДЫХАТЕЛЬНЫХ ПУТЕЙ\nУбедиться, что ничто не перекрывает путь воздуха. Запрокидывание головы с подъёмом подбородка часто устраняет западение языка — самую частую причину обструкции.\n\nB — ОЦЕНКА ДЫХАНИЯ\nПравило «вижу-слышу-чувствую», не дольше десяти секунд. Слишком долгая неуверенная оценка — типичная ошибка, откладывающая необходимые действия.\n\nОСОБЫЙ СЛУЧАЙ: АГОНАЛЬНОЕ ДЫХАНИЕ\nРедкие судорожные вдохи у человека без сознания не считаются полноценным дыханием и не должны останавливать начало реанимации — ошибочная трактовка задокументированно задерживает необходимую помощь.\n\nC — ОЦЕНКА КРОВООБРАЩЕНИЯ\nОценка признаков кровообращения и поиск массивных кровотечений после подтверждения проходимости и дыхания.\n\nПОСЛЕДОВАТЕЛЬНОСТЬ КАК ОБЯЗАТЕЛЬНОЕ ТРЕБОВАНИЕ\nПопытка остановить кровотечение прежде обеспечения проходимости путей у человека без сознания может привести к смерти от асфиксии, даже при успешно остановленном кровотечении.\n\nПЕРВИЧНЫЙ И ВТОРИЧНЫЙ ОСМОТР\nПосле устранения непосредственных угроз — системный осмотр всего тела с головы до ног в одном и том же порядке, чтобы не пропустить повреждение из-за спешки.\n\nРАСШИРЕННЫЕ ВЕРСИИ АЛГОРИТМА\nИногда дополняется буквами D (неврологический статус) и E (осмотр с учётом переохлаждения), но базовая тройка ABC остаётся неизменным ядром.\n\nТИПИЧНЫЕ ОШИБКИ\nПропуск проверки проходимости путей; слишком долгая оценка дыхания; трактовка агонального дыхания как нормального; попытка остановить кровотечение прежде решения проблем с путями и дыханием.\n\nПРОВЕРЬ СЕБЯ\n1. Что означают буквы A, B, C и почему именно в таком порядке?\n2. Какой приём часто восстанавливает проходимость путей у человека без сознания?\n3. Что такое агональное дыхание?\n4. Почему нельзя переходить к следующему этапу, не решив проблему на предыдущем?\n5. Что происходит после завершения алгоритма ABC?'],
['Восстановительное положение','НАЗНАЧЕНИЕ ВОССТАНОВИТЕЛЬНОГО ПОЛОЖЕНИЯ\nПоза на боку для пострадавшего без сознания, но дышащего после ABC — защищает дыхательные пути от западения языка и рвотных масс.\n\nПОЧЕМУ ПОЛОЖЕНИЕ НА СПИНЕ ОПАСНО\nЗащитные рефлексы ослаблены при потере сознания — лежащий на спине рискует захлебнуться рвотными массами, не способными свободно вытечь.\n\nПОШАГОВОЕ ВЫПОЛНЕНИЕ\nБлижняя рука перпендикулярно телу, дальняя — тыльной стороной к щеке, дальняя нога сгибается, поворот за колено и плечо одним движением, голова слегка запрокинута.\n\nПРОВЕРКА ДЫХАНИЯ ПОСЛЕ ПЕРЕВОРОТА\nПромежуточная мера — дыхание проверяется регулярно до прибытия служб, состояние может измениться и потребовать перехода к реанимации.\n\nОГРАНИЧЕНИЯ ПРИМЕНЕНИЯ\nНе применяется при подозрении на травму позвоночника без крайней необходимости и не заменяет реанимацию при отсутствии дыхания.\n\nДЛИТЕЛЬНОЕ ПРЕБЫВАНИЕ В ОДНОМ ПОЛОЖЕНИИ\nПри ожидании дольше получаса — переворот на другой бок во избежание сдавливания нижней руки.\n\nОСОБЕННОСТИ ДЛЯ БЕРЕМЕННЫХ\nПоложение именно на левом боку предотвращает сдавливание маткой крупных сосудов.\n\nСВЯЗЬ С АЛГОРИТМОМ ABC\nЛогическое следствие ABC для случая, когда путь свободен, дыхание и кровообращение есть, а сознание отсутствует.\n\nТИПИЧНЫЕ ОШИБКИ\nПрименение к пострадавшему без дыхания вместо реанимации; отсутствие последующего контроля дыхания; резкие движения при повороте; игнорирование риска сдавливания руки при долгом ожидании.\n\nПРОВЕРЬ СЕБЯ\n1. Для какого состояния предназначено восстановительное положение?\n2. Почему положение на спине опасно при возможной рвоте?\n3. Как выполняется поворот пошагово?\n4. Зачем регулярно проверять дыхание после перевода в положение?\n5. Какая особенность применяется для беременной на позднем сроке?'],
['Вызов экстренных служб и передача информации','ПОЧЕМУ ФОРМА ВЫЗОВА ИМЕЕТ ЗНАЧЕНИЕ\nСтруктурированная информация ускоряет реакцию диспетчера — хаотичное изложение затягивает процесс именно тогда, когда время особенно ценно.\n\nОЧЕРЁДНОСТЬ: ВЫЗОВ ИЛИ ПОМОЩЬ СНАЧАЛА\nПри подозрении на остановку сердца у взрослого — сначала вызов, затем реанимация. Исключение: утопление и дети — сначала минута реанимации, затем вызов, поскольку причина чаще в нехватке кислорода.\n\nСТРУКТУРА ИНФОРМАЦИИ ДЛЯ ДИСПЕТЧЕРА\nМесто происшествия первым, затем что произошло, число пострадавших, их состояние, обратный номер — место первым на случай обрыва связи.\n\nОТВЕТЫ НА ВОПРОСЫ, А НЕ ТОЛЬКО МОНОЛОГ\nДиспетчеры используют стандартизированный протокол вопросов — отвечать конкретно, не пересказывать всё заново, не предполагать диагноз без вопроса.\n\nПРАВИЛО «НЕ КЛАДИТЕ ТРУБКУ ПЕРВЫМ»\nЗавершение инициирует диспетчер — он может дать инструкции по помощи до прибытия бригады уже после кажущегося конца разговора.\n\nОБОЗНАЧЕНИЕ МЕСТА ДЛЯ БРИГАДЫ\nПри труднонаходимом месте — встретить бригаду заметным человеком у входа, экономит время поиска.\n\nОСОБЕННОСТИ ПРИ МАССОВЫХ ПРОИСШЕСТВИЯХ\nОриентировочное число пострадавших и характер происшествия сообщаются как можно раньше — определяет число и профиль направляемых бригад.\n\nТИПИЧНЫЕ ОШИБКИ\nНачало с состояния пострадавшего вместо места происшествия; монолог вместо ответов на вопросы; завершение разговора по своей инициативе; задержка вызова ради самостоятельных попыток там, где вызов должен быть первым.\n\nПРОВЕРЬ СЕБЯ\n1. Что идёт первым при подозрении на остановку сердца и какое есть исключение?\n2. Какая информация сообщается диспетчеру в первую очередь?\n3. Почему важно отвечать на конкретные вопросы диспетчера?\n4. Кто завершает разговор с диспетчером?\n5. Какая информация приоритетна при массовом происшествии?'],
['Сердечно-лёгочная реанимация взрослого','КОГДА НАЧИНАТЬ РЕАНИМАЦИЮ\nРеанимация начинается немедленно при отсутствии сознания и нормального дыхания (включая агональное дыхание, не считающееся нормальным). Долгий поиск пульса не рекомендуется человеку без подготовки — потеря времени опаснее, чем начало компрессий у человека с работающим сердцем.\n\nПОЛОЖЕНИЕ РУК ДЛЯ КОМПРЕССИЙ\nОснование ладони на центре грудины, вторая рука поверх, руки прямые в локтях, плечи над руками — используется вес тела, а не изолированная сила рук.\n\nЧАСТОТА И ГЛУБИНА КОМПРЕССИЙ\nСто-сто двадцать компрессий в минуту, глубина пять-шесть сантиметров, с полным возвратом грудной клетки между компрессиями — неполный возврат мешает сердцу наполниться кровью.\n\nСООТНОШЕНИЕ КОМПРЕССИЙ И ДЫХАНИЯ\nТридцать компрессий на два вдоха. Только компрессии без дыхания допустимы при психологическом барьере — это значительно лучше полного бездействия, хотя полный протокол статистически эффективнее.\n\nПРИЗНАКИ ЭФФЕКТИВНОСТИ И КОГДА ОСТАНАВЛИВАТЬСЯ\nПродолжается до восстановления признаков жизни, прибытия профессиональной помощи или полного истощения спасателя — субъективная оценка безнадёжности не считается основанием для остановки.\n\nСМЕНА СПАСАТЕЛЕЙ\nКаждые около двух минут при нескольких участниках — качество компрессий снижается от утомления незаметно для самого уставшего.\n\nОСОБЕННОСТИ НА РАЗНЫХ ПОВЕРХНОСТЯХ\nТвёрдая опора под спиной обязательна — на мягкой поверхности часть усилия поглощается проседанием.\n\nСВЯЗЬ С ДЕФИБРИЛЛЯЦИЕЙ\nРеанимация поддерживает кровообращение, но чаще именно разряд дефибриллятора восстанавливает нормальный ритм — выполняются параллельно, не вместо друг друга.\n\nТИПИЧНЫЕ ОШИБКИ\nДолгий поиск пульса перед началом; недостаточная глубина из страха повредить рёбра; неполный возврат грудной клетки; реанимация на мягкой поверхности.\n\nПРОВЕРЬ СЕБЯ\n1. Почему не рекомендуется долго искать пульс перед началом реанимации?\n2. Какова частота и глубина компрессий у взрослого?\n3. Какое соотношение компрессий и вдохов и какая есть альтернатива?\n4. При каких трёх условиях реанимация прекращается?\n5. Почему компрессии на мягкой поверхности менее эффективны?'],
['Автоматический наружный дефибриллятор','ПРИНЦИП ДЕЙСТВИЯ ДЕФИБРИЛЛЯТОРА\nРазряд прерывает хаотичную электрическую активность сердца (фибрилляцию), давая собственному водителю ритма шанс восстановить нормальное сокращение — устройство не «запускает» остановившееся сердце, а прерывает хаотичный ритм.\n\nПОЧЕМУ УСТРОЙСТВО АВТОМАТИЧЕСКОЕ\nСамо анализирует ритм через электроды и решает, нужен ли разряд — не нанесёт его при неподходящем ритме, что делает применение безопасным для неподготовленного человека.\n\nПОСЛЕДОВАТЕЛЬНОСТЬ ДЕЙСТВИЙ\nВключение, наложение двух электродов по схеме на них самих (под правой ключицей и на левом боку), автоматический анализ ритма, голосовая команда не прикасаться при разряде.\n\nПОДГОТОВКА ГРУДНОЙ КЛЕТКИ\nКожа должна быть сухой и по возможности без чрезмерной волосистости — большинство комплектов включают бритву, но её отсутствие не повод для длительной задержки.\n\nБЕЗОПАСНОСТЬ ОПЕРАТОРА\nНикто не должен прикасаться к пострадавшему в момент разряда — оператор визуально проверяет это перед разрядом, особенно важно при группе людей вокруг.\n\nПРОДОЛЖЕНИЕ РЕАНИМАЦИИ МЕЖДУ АНАЛИЗАМИ\nКомпрессии возобновляются сразу после разряда или после решения, что он не нужен — реанимация и дефибрилляция работают в паре.\n\nОСОБЫЕ ОБСТОЯТЕЛЬСТВА\nМеталлические украшения снимают, электрод у кардиостимулятора смещают на несколько сантиметров в сторону, на мокрой поверхности пострадавшего переносят в сухое место.\n\nДОСТУПНОСТЬ В ОБЩЕСТВЕННЫХ МЕСТАХ\nРазмещаются в местах с высокой проходимостью именно с расчётом на использование случайными свидетелями без подготовки.\n\nТИПИЧНЫЕ ОШИБКИ\nДолгое прерывание компрессий ради поиска устройства вместо параллельных действий; задержка из-за отсутствия бритвы; прикосновение в момент разряда; электрод поверх видимого кардиостимулятора.\n\nПРОВЕРЬ СЕБЯ\n1. Что на самом деле делает разряд дефибриллятора?\n2. Почему устройство автоматическое и чем это безопасно для неподготовленного человека?\n3. Что нужно сделать с кожей груди перед электродами?\n4. Кто проверяет отсутствие контакта с пострадавшим в момент разряда?\n5. Как накладывать электрод при видимом кардиостимуляторе?'],
['Помощь при удушье (приём Геймлиха)','РАЗЛИЧИЕ ПОЛНОЙ И ЧАСТИЧНОЙ ОБСТРУКЦИИ\nПри частичной обструкции пострадавший ещё кашляет и дышит частично — поощряется собственный кашель, без физического вмешательства, которое может протолкнуть предмет глубже. Полная обструкция — невозможность кашлять, говорить, дышать.\n\nКОГДА ПЕРЕХОДИТЬ К АКТИВНЫМ ДЕЙСТВИЯМ\nТолько при полной обструкции или ослаблении кашля до неэффективного — счёт идёт на минуты.\n\nУДАРЫ МЕЖДУ ЛОПАТКАМИ\nДо пяти резких ударов основанием ладони между лопатками при наклоне пострадавшего вперёд — часто эффективно уже на этом этапе.\n\nПОДДИАФРАГМАЛЬНЫЕ ТОЛЧКИ\nПри неэффективности — обхват талии сзади, кулак чуть выше пупка, резкий толчок внутрь и вверх, создающий искусственный кашлевой импульс.\n\nЧЕРЕДОВАНИЕ ДВУХ ПРИЁМОВ\nЦиклами по пять ударов и пять толчков до удаления предмета, потери сознания или прибытия помощи — оба приёма равноправны.\n\nОСОБЫЙ СЛУЧАЙ: БЕРЕМЕННЫЕ И ИЗБЫТОЧНЫЙ ВЕС\nТочка смещается на середину грудины вместо живота, если обхват талии невозможен или опасен для беременной матки.\n\nПОМОЩЬ САМОМУ СЕБЕ\nСобственный кулак резко на точку выше пупка, либо резкий наклон животом на твёрдый край мебели.\n\nПРИ ПОТЕРЕ СОЗНАНИЯ\nПереход к реанимации, с проверкой рта на видимое инородное тело перед каждым вдохом — компрессии сами создают то же давление, способное вытолкнуть предмет.\n\nТИПИЧНЫЕ ОШИБКИ\nВмешательство при эффективном частичном кашле; попытка извлечь предмет пальцами вслепую; стандартный толчок беременной вместо смещения на грудину; отказ от перехода к реанимации при потере сознания.\n\nПРОВЕРЬ СЕБЯ\n1. Как отличить частичную обструкцию от полной?\n2. Почему не следует вмешиваться при эффективном частичном кашле?\n3. Как выполняются удары между лопатками и поддиафрагмальные толчки?\n4. Как меняется техника для беременной на позднем сроке?\n5. Что делать перед каждым вдохом при потере сознания пострадавшим?'],
['Реанимация детей и младенцев','ПОЧЕМУ НУЖЕН ОТДЕЛЬНЫЙ ПРОТОКОЛ\nМеньший размер грудной клетки и иная частая причина остановки (дыхательная, а не сердечная) делают взрослый протокол не просто неоптимальным, а способным навредить при избыточной силе.\n\nВОЗРАСТНЫЕ ГРАНИЦЫ\nМладенец — примерно до года, ребёнок — от года до полового созревания. Визуальная оценка возраста важнее точного паспортного в моменте.\n\nПРИОРИТЕТ ДЫХАНИЯ У ДЕТЕЙ\nНачало с пяти вдохов прежде первого цикла компрессий — восстановление кислорода особенно важно при вероятной дыхательной причине.\n\nГЛУБИНА И ТЕХНИКА У РЕБЁНКА\nОколо трети переднезаднего размера грудной клетки — примерно пять сантиметров у ребёнка, четыре у младенца. Допустима компрессия одной рукой у ребёнка.\n\nТЕХНИКА У МЛАДЕНЦА\nДва пальца одной руки (один спасатель) или обхват с компрессией большими пальцами (два спасателя) — вся ладонь создаёт риск травмирующей силы.\n\nСООТНОШЕНИЕ КОМПРЕССИЙ И ВДОХОВ\nДля одного неподготовленного спасателя допустимо то же тридцать к двум для простоты запоминания под стрессом.\n\nИСКУССТВЕННОЕ ДЫХАНИЕ МЛАДЕНЦУ\nРот спасателя охватывает и рот, и нос младенца, объём вдоха меньше — ориентир на видимый, но не чрезмерный подъём грудной клетки.\n\nОСОБЕННОСТИ ВЫЗОВА СЛУЖБ\nПри одном спасателе — сначала минута реанимации, затем вызов, в отличие от взрослого протокола, где вызов обычно первый.\n\nЭМОЦИОНАЛЬНАЯ СОСТАВЛЯЮЩАЯ\nРеанимация ребёнка вызывает более острую эмоциональную реакцию — осознание этого заранее помогает не дать стрессу парализовать действия.\n\nТИПИЧНЫЕ ОШИБКИ\nВзрослая техника компрессий на ребёнке; пропуск начальных пяти вдохов; избыточный объём воздуха младенцу; вызов служб прежде начала реанимации при одном спасателе.\n\nПРОВЕРЬ СЕБЯ\n1. Почему протокол для ребёнка нельзя механически заимствовать из взрослого?\n2. Чем начало реанимации у детей отличается от взрослого протокола?\n3. Как отличается техника компрессий у младенца от ребёнка и взрослого?\n4. Как выполняется искусственное дыхание младенцу?\n5. В каком порядке вызов служб и начало реанимации при одном спасателе и ребёнке?'],
['Виды кровотечений и их распознавание','ЗАЧЕМ РАЗЛИЧАТЬ ВИДЫ КРОВОТЕЧЕНИЙ\nТактика первой помощи напрямую зависит от типа повреждённого сосуда: артериальное кровотечение убивает за минуты и требует немедленной агрессивной остановки, тогда как венозное и капиллярное почти всегда можно остановить простым давлением. Ошибочная недооценка типа кровотечения — частая причина предотвратимой смерти при травмах, отмечаемая в материалах Красного Креста и протоколах TCCC.\n\nАРТЕРИАЛЬНОЕ КРОВОТЕЧЕНИЕ\nКровь ярко-алая (насыщена кислородом), вытекает пульсирующей струёй синхронно с сердцебиением, объём кровопотери нарастает стремительно. Наиболее опасный тип, требующий немедленного прямого давления и, при сильном кровотечении конечности, жгута.\n\nВЕНОЗНОЕ КРОВОТЕЧЕНИЕ\nКровь тёмно-красная (бедна кислородом), вытекает равномерной непрерывной струёй без пульсации. Опасно при повреждении крупных вен (шея, бедро) из-за объёма, но обычно останавливается давящей повязкой без жгута.\n\nКАПИЛЛЯРНОЕ КРОВОТЕЧЕНИЕ\nМедленное сочение крови по всей поверхности раны (ссадины, поверхностные порезы). Останавливается самостоятельно или простым прижатием чистой тканью в течение нескольких минут, не требует специальных мер.\n\nВНУТРЕННЕЕ КРОВОТЕЧЕНИЕ: СКРЫТАЯ УГРОЗА\nНе видно снаружи, но проявляется признаками: бледность, холодный пот, учащённый слабый пульс, боль и вздутие живота, кашель или рвота с кровью. Заподозрив внутреннее кровотечение по этим признакам, необходимо немедленно вызывать скорую — первая помощь ограничена покоем и контролем состояния.\n\nОЦЕНКА ОБЪЁМА КРОВОПОТЕРИ КАК КРИТЕРИЙ СРОЧНОСТИ\nПромокание насквозь одежды или повязки за несколько минут, лужа крови на полу диаметром более 20-25 см — ориентировочные признаки значительной кровопотери, требующей вызова экстренных служб независимо от того, удалось ли остановить кровотечение.\n\nТИПИЧНЫЕ ОШИБКИ\nНедооценка артериального кровотечения из-за небольшой видимой раны; попытки определить тип кровотечения слишком долго вместо немедленного начала давления; игнорирование признаков внутреннего кровотечения при отсутствии видимой раны.\n\nПРОВЕРЬ СЕБЯ\n1. Чем артериальное кровотечение отличается от венозного по внешним признакам?\n2. Как останавливается капиллярное кровотечение?\n3. Какие признаки указывают на внутреннее кровотечение?\n4. По каким ориентирам можно оценить объём кровопотери на месте?\n5. Почему нельзя долго определять тип кровотечения перед началом помощи?'],
['Остановка кровотечения аптечными средствами','ПОСЛЕДОВАТЕЛЬНОСТЬ ДЕЙСТВИЙ ПРИ ЛЮБОМ ЗНАЧИМОМ КРОВОТЕЧЕНИИ\nПрямое давление на рану через стерильную салфетку → давящая повязка поверх → при неэффективности — жгут выше раны (для конечностей) или тампонирование раны гемостатическим бинтом (для ран, где жгут неприменим). Эта последовательность отражена в протоколах TCCC (Tactical Combat Casualty Care), адаптированных для гражданского применения.\n\nПРЯМОЕ ДАВЛЕНИЕ КАК ПЕРВЫЙ И ГЛАВНЫЙ ПРИЁМ\nСтерильная салфетка (или чистая ткань при её отсутствии) прижимается непосредственно к ране ладонью с постоянным сильным давлением не менее 10 минут без прерывания для проверки — преждевременное снятие давления для осмотра раны срывает формирующийся сгусток.\n\nДАВЯЩАЯ ПОВЯЗКА\nПосле первичного давления накладывается тугая повязка бинтом поверх салфетки, сохраняющая давление без постоянного участия спасателя — важно проверять, что повязка не пережимает конечность полностью (контроль цвета и температуры кожи ниже повязки).\n\nГЕМОСТАТИЧЕСКИЕ СРЕДСТВА\nГемостатические бинты и порошки (на основе каолина или хитозана), входящие в расширенные аптечки, ускоряют свёртывание при сильных кровотечениях, не поддающихся простому давлению — накладываются непосредственно в рану с последующим тугим бинтованием.\n\nКОГДА ПЕРЕХОДИТЬ К ЖГУТУ\nЕсли прямое давление и давящая повязка не останавливают артериальное кровотечение конечности в течение 1-2 минут, либо кровотечение изначально катастрофическое — немедленно накладывается жгут, без дальнейших попыток давления, согласно современным протоколам TCCC, отдающим приоритет жгуту при массивной кровопотере конечности.\n\nФИКСАЦИЯ ВРЕМЕНИ И ПЕРЕДАЧА ИНФОРМАЦИИ\nВремя наложения жгута или начала давящей повязки обязательно фиксируется (запись на коже пострадавшего или бумаге) и сообщается прибывшим медикам — эта информация напрямую влияет на дальнейшую тактику лечения.\n\nТИПИЧНЫЕ ОШИБКИ\nПериодическое снятие повязки "проверить, остановилось ли"; слишком слабое или слишком непродолжительное прямое давление; промедление с переходом к жгуту при явно массивном кровотечении; отсутствие фиксации времени наложения жгута.\n\nПРОВЕРЬ СЕБЯ\n1. Опишите последовательность действий при значимом кровотечении.\n2. Почему нельзя прерывать прямое давление для осмотра раны?\n3. Для чего нужны гемостатические средства?\n4. Когда нужно переходить от давящей повязки к жгуту?\n5. Зачем фиксировать время наложения жгута?'],
['Импровизированный жгут и давящая повязка','КОГДА НЕТ ГОТОВОГО ЖГУТА\nПри отсутствии табельного кровоостанавливающего жгута (типа CAT) в аптечке или при полном отсутствии аптечки применяются импровизированные средства, при соблюдении тех же принципов: широкая полоса материала, достаточная сила затягивания, точное время наложения.\n\nВЫБОР МАТЕРИАЛА ДЛЯ ИМПРОВИЗИРОВАННОГО ЖГУТА\nШирокий ремень, свёрнутая в жгут плотная ткань (шарф, футболка) шириной не менее 4-5 см — узкие предметы (верёвка, тонкий шнур, провод) повреждают ткани и нервы под жгутом и категорически не рекомендуются медицинскими протоколами.\n\nТЕХНИКА НАЛОЖЕНИЯ ИМПРОВИЗИРОВАННОГО ЖГУТА\nНакладывается на 5-7 см выше раны (не на сустав), с использованием палки или подобного предмета как рычага (закрутка) для достижения достаточного затягивающего усилия — простой узел без закрутки почти никогда не создаёт давление, достаточное для остановки артериального кровотечения.\n\nКОНТРОЛЬ ЭФФЕКТИВНОСТИ ЖГУТА\nКровотечение должно полностью прекратиться, пульс ниже жгута должен исчезнуть — если кровотечение продолжается, жгут наложен недостаточно туго и требует дозатяжки; чрезмерно слабый жгут пережимает вены, но не артерии, что усиливает кровотечение.\n\nИМПРОВИЗИРОВАННАЯ ДАВЯЩАЯ ПОВЯЗКА\nЛюбая чистая ткань (одежда, полотенце) как заменитель стерильной салфетки, сложенная в несколько слоёв, плюс любой длинный отрез ткани для тугого бинтования поверх — принцип идентичен аптечному варианту, отличие только в материале.\n\nВРЕМЕННЫЕ ОГРАНИЧЕНИЯ ЖГУТА НЕЗАВИСИМО ОТ МАТЕРИАЛА\nМаксимально допустимое время без ослабления — около часа (согласно современным протоколам TCCC, ранее рекомендовавшийся регулярный ослабляющий контроль каждые 15-20 минут сейчас не рекомендуется как повышающий кровопотерю) — при длительной транспортировке точное время сообщается медикам, которые примут решение о снятии.\n\nТИПИЧНЫЕ ОШИБКИ\nИспользование узкого шнура или провода; наложение жгута без рычага-закрутки, недостаточное для остановки артериального кровотечения; наложение на сустав вместо мышечной части конечности; регулярное самостоятельное ослабление жгута "для отдыха тканей" вопреки современным рекомендациям.\n\nПРОВЕРЬ СЕБЯ\n1. Какой материал подходит для импровизированного жгута, а какой нет?\n2. Как использовать рычаг-закрутку при наложении?\n3. Как проверить, что жгут наложен достаточно туго?\n4. Из чего можно сделать импровизированную давящую повязку?\n5. Какое максимальное время допустимо для наложенного жгута?'],
['Ампутации и травматические отрывы','ОСОБЫЙ СЛУЧАЙ МАССИВНОЙ ТРАВМЫ\nТравматическая ампутация (полный или частичный отрыв конечности или её части) сочетает две задачи: остановку катастрофического кровотечения у пострадавшего и правильное сохранение отделённой части тела для возможной реплантации в стационаре.\n\nПЕРВООЧЕРЁДНОЕ ДЕЙСТВИЕ: ОСТАНОВКА КРОВОТЕЧЕНИЯ У ПОСТРАДАВШЕГО\nНемедленное наложение жгута выше уровня травмы — при полной ампутации конечности это делается без колебаний и без попыток прямого давления на культю, так как кровопотеря при таких травмах развивается стремительно и представляет непосредственную угрозу жизни.\n\nЧТО ДЕЛАТЬ С ОТДЕЛЁННОЙ ЧАСТЬЮ\nЗавернуть в чистую, слегка увлажнённую (не мокрую) ткань, поместить в чистый пакет, который затем поместить в ёмкость со льдом или холодной водой — часть НЕ должна напрямую соприкасаться со льдом или водой, что повреждает ткани и снижает шансы на реплантацию.\n\nЧАСТИЧНЫЙ ОТРЫВ (ЧАСТЬ ТКАНЕЙ СОХРАНЯЕТ СВЯЗЬ)\nНе отделять полностью самостоятельно — зафиксировать в максимально естественном анатомическом положении, остановить кровотечение давлением или жгутом выше места травмы, транспортировать с сохранением этого положения.\n\nОБЕЗБОЛИВАНИЕ И ПСИХОЛОГИЧЕСКАЯ ПОДДЕРЖКА\nПострадавший при такой травме часто в состоянии шока — важно говорить спокойно, не показывать паники, контролировать признаки шока (см. тему судорожного приступа и потери сознания далее в программе) до прибытия медиков.\n\nНЕМЕДЛЕННЫЙ ВЫЗОВ ЭКСТРЕННЫХ СЛУЖБ С ТОЧНЫМ ОПИСАНИЕМ\nПри вызове чётко указать характер травмы (полная/частичная ампутация, локализация) — это определяет, какая бригада и с каким оснащением будет направлена, а также подготовку принимающего стационара к возможной реплантации.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка приложить отделённую часть непосредственно в лёд; промедление с наложением жгута из-за колебаний; попытка самостоятельно "дообрезать" частично держащиеся ткани; транспортировка отделённой части в неподходящем открытом контейнере.\n\nПРОВЕРЬ СЕБЯ\n1. Какое действие является первоочередным при травматической ампутации?\n2. Как правильно сохранить отделённую часть тела?\n3. Чем действия при частичном отрыве отличаются от полной ампутации?\n4. Почему важна психологическая поддержка пострадавшего при такой травме?\n5. Что нужно чётко сообщить при вызове экстренных служб?'],
['Переломы и правила иммобилизации','РАСПОЗНАВАНИЕ ПЕРЕЛОМА\nЯвные признаки: неестественное положение конечности, деформация, укорочение, отёк и стремительно нарастающая гематома, невозможность опоры или движения, характерный хруст в момент травмы. При открытом переломе кость видна в ране — такой перелом всегда сопровождается значительным риском кровотечения и инфицирования.\n\nОБЩИЙ ПРИНЦИП ИММОБИЛИЗАЦИИ\nЗафиксировать повреждённую конечность в том положении, в котором она находится, захватывая два соседних сустава (выше и ниже места перелома) — попытки выпрямить или вправить перелом самостоятельно категорически запрещены и могут повредить сосуды и нервы.\n\nШИНИРОВАНИЕ АПТЕЧНЫМИ СРЕДСТВАМИ\nСтандартные шины (лестничные, пневматические, вакуумные из расширенной аптечки) накладываются с мягкой прокладкой между шиной и конечностью, фиксируются бинтом достаточно туго для неподвижности, но без пережатия кровообращения.\n\nОТКРЫТЫЙ ПЕРЕЛОМ: ДОПОЛНИТЕЛЬНЫЕ ДЕЙСТВИЯ\nСначала останавливается кровотечение и накладывается стерильная повязка на рану вокруг видимой кости (без попытки вправить её обратно), затем производится иммобилизация тем же принципом, что и при закрытом переломе.\n\nПРИЗНАКИ НАРУШЕНИЯ КРОВООБРАЩЕНИЯ ПОСЛЕ ШИНИРОВАНИЯ\nПобледнение или посинение пальцев, онемение, отсутствие пульса ниже места травмы — при появлении этих признаков шину необходимо немедленно ослабить, поскольку неправильная иммобилизация сама по себе способна вызвать тяжёлое повреждение тканей.\n\nОБЕЗБОЛИВАНИЕ И ПОКОЙ ДО ПРИБЫТИЯ ПОМОЩИ\nПридать пострадавшему удобное положение, минимизировать любые движения повреждённой части, контролировать признаки шока при значительных переломах (особенно бедра и таза, сопровождающихся большой скрытой кровопотерей).\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка вправить перелом или "проверить", насколько он серьёзен, подвигав конечностью; фиксация только места перелома без захвата соседних суставов; слишком тугое бинтование шины, нарушающее кровообращение; попытка вправить кость при открытом переломе обратно в рану.\n\nПРОВЕРЬ СЕБЯ\n1. По каким признакам можно заподозрить перелом?\n2. Какой общий принцип лежит в основе иммобилизации?\n3. Чем отличаются действия при открытом переломе?\n4. Какие признаки говорят о нарушении кровообращения после шинирования?\n5. Почему нельзя пытаться вправить перелом самостоятельно?'],
['Импровизированные шины из подручных материалов','ПРИНЦИП НЕ МЕНЯЕТСЯ БЕЗ АПТЕЧКИ\nОтсутствие табельной шины не отменяет саму задачу иммобилизации — она решается любым достаточно жёстким и достаточно длинным предметом, способным зафиксировать сустав выше и ниже перелома, при соблюдении тех же правил мягкой прокладки и умеренного натяжения фиксации.\n\nМАТЕРИАЛЫ ДЛЯ ИМПРОВИЗИРОВАННОЙ ШИНЫ\nДоски, палки, зонты, лыжные палки, свёрнутые в трубку журналы или плотный картон, куски фанеры — любой достаточно жёсткий и не сгибающийся под весом конечности предмет соответствующей длины.\n\nФИКСАЦИЯ ПРИ ПОЛНОМ ОТСУТСТВИИ ЖЁСТКИХ ПРЕДМЕТОВ\nИммобилизация ноги — прибинтовыванием к здоровой ноге (метод "нога к ноге"); иммобилизация руки — прибинтовыванием или примотыванием к туловищу, что также ограничивает движение без внешней жёсткой опоры.\n\nМЯГКАЯ ПРОКЛАДКА ИЗ ПОДРУЧНЫХ МАТЕРИАЛОВ\nОдежда, полотенца, любая ткань — оборачивается вокруг жёсткого материала шины и вокруг конечности в местах контакта, чтобы избежать давления жёсткого края на кожу и подлежащие ткани при длительной фиксации.\n\nФИКСИРУЮЩИЙ МАТЕРИАЛ ПРИ ОТСУТСТВИИ БИНТА\nПолосы ткани, ремни, галстуки, шнурки, скотч (с осторожностью, не вплотную к коже) — любой достаточно прочный и не растягивающийся материал, позволяющий надёжно, но не туго закрепить шину.\n\nОГРАНИЧЕНИЯ ИМПРОВИЗИРОВАННОЙ ИММОБИЛИЗАЦИИ\nИмпровизированная шина хуже держит форму при длительной транспортировке и требует более частой проверки кровообращения ниже места фиксации, чем табельная — это компромиссное, а не идеальное решение, применяемое до прибытия профессиональной помощи.\n\nТИПИЧНЫЕ ОШИБКИ\nИспользование слишком коротких или гибких предметов, не обеспечивающих жёсткость; отсутствие мягкой прокладки, приводящее к дополнительным повреждениям кожи; излишне тугая фиксация подручным материалом; отказ от иммобилизации из-за отсутствия "правильных" средств.\n\nПРОВЕРЬ СЕБЯ\n1. Меняется ли принцип иммобилизации при отсутствии табельной шины?\n2. Какие подручные материалы подходят для шины?\n3. Как иммобилизировать ногу при полном отсутствии жёстких предметов?\n4. Зачем нужна мягкая прокладка между шиной и конечностью?\n5. В чём ограничение импровизированной иммобилизации по сравнению с табельной?'],
['Травмы позвоночника и шеи','ПОЧЕМУ ЭТА ТРАВМА ТРЕБУЕТ ОСОБОЙ ОСТОРОЖНОСТИ\nВ отличие от переломов конечностей, неправильное движение при травме позвоночника способно превратить обратимое повреждение в необратимое повреждение спинного мозга и паралич — базовый принцип первой помощи здесь: минимальное движение пострадавшего, а не активные действия.\n\nКОГДА ПОДОЗРЕВАТЬ ТРАВМУ ПОЗВОНОЧНИКА\nПадение с высоты, ДТП, удар головой при нырянии на мелководье, любая травма с сильным ударом по голове или спине, жалобы на онемение, покалывание или невозможность пошевелить конечностями после травмы — при любом из этих признаков действовать по протоколу травмы позвоночника, даже без полной уверенности.\n\nПРИНЦИП "НЕ ДВИГАТЬ БЕЗ КРАЙНЕЙ НЕОБХОДИМОСТИ"\nПострадавший остаётся в том положении, в котором находится, если это не создаёт немедленной угрозы жизни (пожар, затопление, продолжающееся разрушение конструкций) — вызов экстренных служб и ожидание бригады со специальным оборудованием предпочтительнее самостоятельного перемещения.\n\nРУЧНАЯ СТАБИЛИЗАЦИЯ ГОЛОВЫ И ШЕИ\nЕсли необходимо удерживать пострадавшего в сознании и на месте, стабилизация выполняется двумя руками с обеих сторон головы, удерживая её на одной линии с позвоночником, без попыток выпрямить наклон или поворот головы, если он уже присутствует.\n\nЕСЛИ ПЕРЕМЕЩЕНИЕ НЕИЗБЕЖНО (УГРОЗА ЖИЗНИ)\nПеремещение производится группой людей одновременно, синхронно, с сохранением оси "голова-шея-позвоночник" без сгибания и скручивания (техника переноса единым блоком) — по возможности с использованием твёрдой поверхности (дверь, доска) в качестве импровизированных носилок.\n\nПОВЕДЕНИЕ С ПОСТРАДАВШИМ В СОЗНАНИИ\nСпокойно объяснить, что двигаться нельзя, даже если пострадавший чувствует себя относительно неплохо и пытается встать — часть повреждений позвоночника не сопровождается сильной болью сразу, что создаёт ложное ощущение безопасности движения.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка усадить или поднять пострадавшего "чтобы было удобнее"; резкие повороты головы при стабилизации; перемещение в одиночку без синхронной группы помощников; недооценка риска при отсутствии сильной боли у пострадавшего.\n\nПРОВЕРЬ СЕБЯ\n1. Почему травма позвоночника требует особой осторожности по сравнению с другими травмами?\n2. При каких обстоятельствах нужно подозревать травму позвоночника?\n3. В чём заключается принцип "не двигать без крайней необходимости"?\n4. Как выполняется ручная стабилизация головы и шеи?\n5. Как правильно перемещать пострадавшего, если это неизбежно?'],
['Транспортировка пострадавшего','КОГДА ТРАНСПОРТИРОВКА НЕОБХОДИМА СВОИМИ СИЛАМИ\nПри невозможности дождаться скорой помощи (труднодоступная местность, массовые происшествия с недостатком бригад, немедленная угроза на месте) может потребоваться самостоятельная транспортировка — выполняется только после первичной остановки кровотечения и иммобилизации переломов.\n\nСПОСОБЫ ПЕРЕНОСКИ ОДНИМ ЧЕЛОВЕКОМ\nПереноска на спине, переноска "на руках" для более лёгких пострадавших, метод перетаскивания за одежду в подмышках при невозможности поднять (например, для эвакуации из опасной зоны на короткое расстояние) — каждый способ подходит для разных состояний и дистанций.\n\nПЕРЕНОСКА ГРУППОЙ (2-4 ЧЕЛОВЕКА)\nБолее безопасна и предпочтительна при наличии нескольких помощников: перенос "друг за другом" с поддержкой под спину и колени, использование импровизированных носилок (дверь, доска, куртки, продетые на две палки) — минимизирует риск дополнительной травмы пострадавшего.\n\nИМПРОВИЗИРОВАННЫЕ НОСИЛКИ ИЗ ПОДРУЧНЫХ СРЕДСТВ\nДве прочные палки продеваются через рукава двух-трёх застёгнутых курток — простая и проверенная конструкция для переноски на короткие и средние расстояния при отсутствии другого твёрдого основания.\n\nПОЛОЖЕНИЕ ПОСТРАДАВШЕГО ПРИ ТРАНСПОРТИРОВКЕ\nОпределяется типом травмы: с подозрением на травму позвоночника — строго горизонтально на твёрдой поверхности; в шоковом состоянии — приподнятые ноги (при отсутствии травм ног/таза); при травмах груди — полусидя, если это не противоречит другим ограничениям.\n\nКОГДА ТРАНСПОРТИРОВКА ОПАСНЕЕ ОЖИДАНИЯ\nПри подозрении на травму позвоночника или таза без крайней необходимости (непосредственная угроза жизни на месте) самостоятельная транспортировка сопряжена с большим риском, чем ожидание специализированной бригады — это решение взвешивается по обстоятельствам, а не выполняется автоматически.\n\nТИПИЧНЫЕ ОШИБКИ\nТранспортировка до остановки кровотечения или иммобилизации переломов; переноска в одиночку тяжёлого пострадавшего там, где можно подождать помощь; неправильное положение тела при транспортировке относительно типа травмы; резкие движения при перекладывании на носилки.\n\nПРОВЕРЬ СЕБЯ\n1. В каких случаях оправдана самостоятельная транспортировка пострадавшего?\n2. Какие способы переноски одним человеком существуют?\n3. Как сделать импровизированные носилки из курток и палок?\n4. Как положение тела при транспортировке зависит от типа травмы?\n5. Когда транспортировка опаснее, чем ожидание помощи на месте?'],
['Термические ожоги: степени и первая помощь','КЛАССИФИКАЦИЯ ОЖОГОВ ПО СТЕПЕНИ\nПервая степень — покраснение и боль без волдырей (поверхностный слой кожи); вторая степень — волдыри, выраженная боль, повреждение более глубокого слоя; третья степень — повреждение всех слоёв кожи, обугливание или белесый вид, часто безболезненное из-за разрушения нервных окончаний, что парадоксально указывает на большую тяжесть.\n\nПЕРВОЕ ДЕЙСТВИЕ ПРИ ЛЮБОМ ТЕРМИЧЕСКОМ ОЖОГЕ\nНемедленное охлаждение прохладной (не ледяной) проточной водой в течение 10-20 минут — это останавливает дальнейшее термическое повреждение тканей, которое продолжается ещё некоторое время после прекращения контакта с источником ожога.\n\nЧТО НЕЛЬЗЯ ДЕЛАТЬ ПРИ ОЖОГАХ\nПрикладывать лёд напрямую (вызывает дополнительное повреждение холодом), наносить масло, сметану, зубную пасту или другие бытовые "народные" средства (создают плёнку, удерживающую тепло, и повышают риск инфицирования), прокалывать образовавшиеся волдыри самостоятельно.\n\nОЦЕНКА ПЛОЩАДИ ОЖОГА: ПРАВИЛО ЛАДОНИ\nПлощадь ладони пострадавшего примерно равна 1% площади поверхности его тела — это простой ориентир для оценки обширности ожога на месте происшествия без специального оборудования.\n\nКОГДА ОЖОГ ТРЕБУЕТ НЕМЕДЛЕННОЙ ГОСПИТАЛИЗАЦИИ\nОжоги третьей степени любой площади, ожоги второй степени площадью более 5-10% поверхности тела, ожоги лица, кистей, стоп, паха или крупных суставов, ожоги у детей и пожилых людей — во всех этих случаях вызывается скорая помощь независимо от кажущейся переносимости боли.\n\nПОВЯЗКА ПОСЛЕ ОХЛАЖДЕНИЯ\nСухая стерильная неприлипающая повязка (специальные ожоговые повязки из аптечки или чистая ткань) накладывается свободно, без давления на повреждённую поверхность — цель защитить рану от загрязнения, не создавая дополнительного давления на повреждённые ткани.\n\nТИПИЧНЫЕ ОШИБКИ\nИспользование льда вместо прохладной воды; применение народных средств (масло, сметана); прокалывание волдырей; недооценка тяжести безболезненного ожога третьей степени; недостаточное время охлаждения.\n\nПРОВЕРЬ СЕБЯ\n1. Чем отличаются друг от друга три степени ожогов?\n2. Какое действие первично при любом термическом ожоге?\n3. Какие бытовые средства нельзя использовать при ожогах и почему?\n4. Как оценить площадь ожога по правилу ладони?\n5. При каких признаках ожог требует немедленной госпитализации?'],
['Химические и электрические ожоги','ХИМИЧЕСКИЙ ОЖОГ: ПЕРВОЕ И ГЛАВНОЕ ДЕЙСТВИЕ\nНемедленное обильное промывание проточной водой в течение 15-20 минут — но перед этим необходимо снять одежду, пропитанную химическим веществом, чтобы прекратить продолжающийся контакт вещества с кожей, работая в перчатках, если они доступны, чтобы избежать собственного контакта.\n\nОСОБЫЕ СЛУЧАИ ХИМИЧЕСКИХ ОЖОГОВ\nОжог негашёной известью не промывается водой (реагирует с выделением тепла) — сухой порошок сначала стряхивается механически, и только затем следует обильное промывание; при попадании химического вещества в глаза — немедленное промывание чистой водой в течение 15-20 минут при открытом веке.\n\nЭЛЕКТРИЧЕСКИЙ ОЖОГ: ОПАСНОСТЬ ПРЕЖДЕ ВСЕГО ДЛЯ СПАСАТЕЛЯ\nПеред оказанием помощи необходимо убедиться в отключении источника тока (выключить электричество, отодвинуть провод сухим непроводящим предметом — деревянной палкой, сухой пластиковой вещью), ни в коем случае не прикасаясь к пострадавшему, находящемуся под напряжением.\n\nОСОБЕННОСТЬ ЭЛЕКТРИЧЕСКОГО ОЖОГА: НЕВИДИМАЯ ГЛУБИНА ПОВРЕЖДЕНИЯ\nВ отличие от термического, электрический ожог часто выглядит небольшим снаружи (точки входа и выхода тока), но вызывает обширное повреждение тканей по ходу прохождения тока внутри тела, включая возможную остановку сердца — любой удар током средней и высокой мощности требует вызова скорой помощи независимо от вида кожных повреждений.\n\nСЕРДЕЧНЫЙ РИТМ ПОСЛЕ УДАРА ТОКОМ\nЭлектрический ток способен вызвать нарушение сердечного ритма даже без потери сознания в момент травмы — необходимо наблюдение за пострадавшим и готовность к сердечно-лёгочной реанимации при остановке сердца.\n\nОБРАБОТКА КОЖНЫХ ПОВРЕЖДЕНИЙ ПОСЛЕ ОТКЛЮЧЕНИЯ ИСТОЧНИКА\nПосле обеспечения безопасности — стандартная обработка ожоговой раны, аналогичная термическому ожогу (охлаждение при термическом компоненте, стерильная неприлипающая повязка), но с обязательной госпитализацией из-за скрытой глубины повреждения.\n\nТИПИЧНЫЕ ОШИБКИ\nПромывание водой ожога негашёной известью; прикосновение к пострадавшему, находящемуся под напряжением, без отключения источника; недооценка тяжести электротравмы из-за небольшой видимой раны; отказ от вызова скорой при кажущемся хорошем самочувствии после удара током.\n\nПРОВЕРЬ СЕБЯ\n1. Как правильно оказать первую помощь при химическом ожоге?\n2. Какой химический ожог нельзя промывать водой сразу и почему?\n3. Что необходимо сделать перед оказанием помощи при электрическом ожоге?\n4. Почему электрический ожог опаснее, чем кажется по внешнему виду?\n5. За чем нужно наблюдать после удара током, даже без потери сознания?'],
['Обморожение и общее переохлаждение','СТЕПЕНИ ОБМОРОЖЕНИЯ\nПервая степень — побледнение и онемение кожи без повреждения тканей; вторая — образование пузырей после отогревания; третья и четвёртая — повреждение глубоких тканей вплоть до омертвения. Внешне лёгкое на морозе обморожение часто выглядит серьёзнее только после отогревания, когда проявляются пузыри и покраснение.\n\nПЕРВАЯ ПОМОЩЬ ПРИ ОБМОРОЖЕНИИ\nПостепенное отогревание в тёплом помещении (не резко горячей водой или у открытого огня), сухая утепляющая повязка на поражённый участок, тёплое питьё — резкое согревание повреждает и без того ослабленные ткани.\n\nЧТО НЕЛЬЗЯ ДЕЛАТЬ ПРИ ОБМОРОЖЕНИИ\nРастирать обмороженный участок снегом или шерстяной тканью (частое ошибочное "народное" средство, усиливающее повреждение кожи), резко отогревать в горячей воде, прокалывать образовавшиеся пузыри.\n\nОБЩЕЕ ПЕРЕОХЛАЖДЕНИЕ (ГИПОТЕРМИЯ): СТАДИИ\nЛёгкая — дрожь, озноб, сохранена ясность сознания; средняя — прекращение дрожи, спутанность сознания, замедление движений; тяжёлая — потеря сознания, замедление дыхания и сердцебиения, угроза остановки сердца. Прекращение дрожи при продолжающемся переохлаждении — тревожный признак ухудшения, а не улучшения состояния.\n\nПЕРВАЯ ПОМОЩЬ ПРИ ОБЩЕМ ПЕРЕОХЛАЖДЕНИИ\nПереместить в тёплое место, снять мокрую одежду, укутать в сухие тёплые вещи или термоодеяло, тёплое сладкое питьё при сохранённом сознании — при тяжёлой гипотермии движения пострадавшего должны быть минимальны, так как резкая физическая активность способна спровоцировать опасную аритмию сердца.\n\nСВЯЗЬ С ТЕМОЙ РЕАНИМАЦИИ ПРИ ТЯЖЁЛОЙ ГИПОТЕРМИИ\nПри тяжёлой гипотермии пульс и дыхание могут быть настолько замедленными, что их сложно определить обычным способом — рекомендуется проверять пульс дольше обычного (до минуты) перед принятием решения о начале сердечно-лёгочной реанимации, изученной в модуле реанимации.\n\nТИПИЧНЫЕ ОШИБКИ\nРастирание обморожения снегом; резкое отогревание горячей водой; активные физические действия пострадавшего при тяжёлой гипотермии; поспешное заключение об отсутствии пульса при переохлаждении без достаточно долгой проверки.\n\nПРОВЕРЬ СЕБЯ\n1. Какие степени обморожения существуют?\n2. Как правильно отогревать обмороженный участок?\n3. Почему растирание снегом вредно при обморожении?\n4. Назовите стадии общей гипотермии и их признаки.\n5. Почему нельзя допускать активных движений пострадавшего при тяжёлой гипотермии?'],
['Тепловой и солнечный удар','РАЗЛИЧИЕ ТЕПЛОВОГО И СОЛНЕЧНОГО УДАРА\nТепловой удар — перегрев организма при высокой температуре и влажности среды независимо от солнца (душное помещение, тяжёлая физическая работа в жару); солнечный удар — разновидность, вызванная прямым длительным воздействием солнца на голову. Механизм и первая помощь по сути идентичны.\n\nПРИЗНАКИ ТЕПЛОВОГО/СОЛНЕЧНОГО УДАРА\nВысокая температура тела, горячая сухая или, наоборот, липкая от пота кожа, головная боль, головокружение, тошнота, спутанность сознания, в тяжёлых случаях — потеря сознания и судороги. Прекращение потоотделения при сохраняющейся жаре — признак ухудшения, а не улучшения состояния.\n\nПЕРВАЯ ПОМОЩЬ: ОХЛАЖДЕНИЕ КАК ГЛАВНАЯ ЗАДАЧА\nНемедленно переместить в тень или прохладное помещение, снять лишнюю одежду, обмахивать, прикладывать прохладные (не ледяные) влажные компрессы к шее, подмышкам, паху (зоны крупных сосудов, где охлаждение наиболее эффективно), прохладное питьё при сохранённом сознании.\n\nОТЛИЧИЕ ОТ ОБМОРОКА ПРИ ЖАРЕ (ТЕПЛОВОЙ ОБМОРОК)\nБолее лёгкое состояние — кратковременная потеря сознания из-за расширения сосудов в жару, быстро проходит в положении лёжа с приподнятыми ногами в прохладном месте, без выраженного повышения температуры тела, характерного для теплового удара.\n\nКОГДА ВЫЗЫВАТЬ СКОРУЮ НЕМЕДЛЕННО\nПотеря сознания, судороги, температура тела выше 40°C, спутанность сознания, не проходящая после начала охлаждения — эти признаки указывают на состояние, угрожающее жизни, требующее профессиональной медицинской помощи независимо от предпринятых мер охлаждения.\n\nПРОФИЛАКТИКА КАК ЧАСТЬ ТЕМЫ\nДостаточное питьё в жару, лёгкая светлая одежда, головной убор на солнце, ограничение физической активности в пик жары — простые меры, снижающие риск теплового и солнечного удара, уместные для включения в академический курс профилактики.\n\nТИПИЧНЫЕ ОШИБКИ\nИспользование ледяной воды для охлаждения (может вызвать спазм сосудов, ухудшающий теплоотдачу); недооценка тяжести состояния при прекращении потоотделения; путаница тяжёлого теплового удара с лёгким тепловым обмороком; отказ от вызова скорой при явных признаках тяжёлого состояния.\n\nПРОВЕРЬ СЕБЯ\n1. Чем тепловой удар отличается от солнечного?\n2. Какие признаки указывают на тепловой/солнечный удар?\n3. В какие зоны тела прикладываются охлаждающие компрессы и почему именно туда?\n4. Чем тепловой обморок отличается от теплового удара?\n5. При каких признаках необходим немедленный вызов скорой помощи?'],
['Пищевые и бытовые отравления','ПРИЗНАКИ ПИЩЕВОГО ОТРАВЛЕНИЯ\nТошнота, рвота, диарея, боли в животе, слабость, иногда повышение температуры — обычно проявляются от получаса до нескольких часов после употребления некачественной пищи. Тяжесть зависит от возбудителя (бактериальный токсин, вирус) и объёма съеденного.\n\nПЕРВАЯ ПОМОЩЬ ПРИ ПИЩЕВОМ ОТРАВЛЕНИИ\nОбильное питьё небольшими порциями для предотвращения обезвоживания (вода, регидратационные растворы), покой, при сохранённой рвотной реакции — не подавлять её искусственно на начальном этапе, поскольку это защитный механизм выведения токсина.\n\nКОГДА ПИЩЕВОЕ ОТРАВЛЕНИЕ ТРЕБУЕТ СКОРОЙ ПОМОЩИ\nПризнаки сильного обезвоживания (сухость во рту, редкое мочеиспускание, головокружение при вставании), кровь в рвоте или стуле, высокая температура, отравление у маленьких детей или пожилых людей, подозрение на отравление грибами или ботулизм (нарушение зрения, речи, глотания) — во всех этих случаях требуется немедленный вызов скорой.\n\nБЫТОВЫЕ ОТРАВЛЕНИЯ ХИМИЧЕСКИМИ ВЕЩЕСТВАМИ\nПри проглатывании бытовой химии — НЕ вызывать рвоту самостоятельно (едкие вещества повторно повреждают пищевод при обратном прохождении), дать выпить небольшое количество воды для разбавления, немедленно связаться с токсикологическим центром или скорой помощью, сохранив упаковку вещества для передачи медикам.\n\nОСОБЫЙ СЛУЧАЙ: ОТРАВЛЕНИЕ ЛЕКАРСТВАМИ\nОпределить, какое количество и какого препарата принято (передозировка или ошибочный приём), сохранить упаковку или остатки препарата для медиков, не давать "нейтрализующих" средств без консультации со специалистом — самостоятельные меры могут ухудшить состояние при незнании конкретного вещества.\n\nПРИНЦИП: ИНФОРМАЦИЯ ВАЖНЕЕ ДЕЙСТВИЯ ПРИ НЕИЗВЕСТНОМ ВЕЩЕСТВЕ\nПри отравлении неизвестным веществом главная задача первого помощника — не "лечить" самостоятельно, а максимально быстро получить консультацию токсикологического центра по телефону и точно передать информацию о веществе и количестве.\n\nТИПИЧНЫЕ ОШИБКИ\nВызывание рвоты при проглатывании едких химических веществ; подавление рвоты противорвотными средствами на раннем этапе пищевого отравления; недооценка признаков обезвоживания у детей; выбрасывание упаковки вещества, вызвавшего отравление, до приезда медиков.\n\nПРОВЕРЬ СЕБЯ\n1. Какие признаки характерны для пищевого отравления?\n2. Когда пищевое отравление требует немедленного вызова скорой?\n3. Почему нельзя вызывать рвоту при проглатывании бытовой химии?\n4. Что нужно сохранить для медиков при отравлении лекарствами или химией?\n5. Какой принцип главный при отравлении неизвестным веществом?'],
['Отравление угарным газом','ПОЧЕМУ УГАРНЫЙ ГАЗ ОСОБЕННО ОПАСЕН\nНе имеет цвета и запаха, поэтому отравление часто происходит незаметно (неисправная печь, автомобиль в закрытом гараже, пожар) — угарный газ связывается с гемоглобином крови намного прочнее кислорода, вытесняя его и вызывая кислородное голодание тканей, прежде всего мозга и сердца.\n\nРАННИЕ ПРИЗНАКИ ОТРАВЛЕНИЯ\nГоловная боль, головокружение, слабость, тошнота — легко спутать с обычным недомоганием или усталостью, что является главной причиной поздней диагностики; характерный признак — одновременное появление похожих симптомов у нескольких людей в одном помещении.\n\nПРОГРЕССИРОВАНИЕ ПРИ ПРОДОЛЖАЮЩЕМСЯ ВОЗДЕЙСТВИИ\nСпутанность сознания, потеря координации, судороги, потеря сознания, остановка дыхания при высокой концентрации — состояние способно ухудшаться стремительно, особенно у детей и людей с заболеваниями сердца.\n\nПЕРВОЕ И ОБЯЗАТЕЛЬНОЕ ДЕЙСТВИЕ: ПРЕКРАЩЕНИЕ КОНТАКТА С ГАЗОМ\nНемедленно вывести или вынести пострадавшего на свежий воздух, при этом спасатель должен обеспечить собственную безопасность (не заходить в загазованное помещение без вентиляции или средств защиты) — это частая причина того, что при таких происшествиях страдает более одного человека, включая спасателей.\n\nПЕРВАЯ ПОМОЩЬ ПОСЛЕ ВЫВОДА НА ВОЗДУХ\nОбеспечить приток свежего воздуха, при потере сознания — контроль дыхания и пульса, готовность к сердечно-лёгочной реанимации (изучена ранее в программе), при наличии — кислородная маска (в медицинских учреждениях); во всех случаях среднего и тяжёлого отравления обязателен вызов скорой помощи, так как последствия для мозга проявляются иногда с задержкой.\n\nПРОФИЛАКТИКА КАК ЧАСТЬ ТЕМЫ\nУстановка детекторов угарного газа в помещениях с печным отоплением или гаражами, регулярная проверка вентиляции и дымоходов, запрет на прогрев автомобиля в закрытом гараже — простые меры значительно снижают риск отравления.\n\nТИПИЧНЫЕ ОШИБКИ\nИгнорирование ранних симптомов, похожих на обычное недомогание; вход в загазованное помещение без обеспечения собственной безопасности; отказ от вызова скорой при кажущемся быстром улучшении состояния на свежем воздухе.\n\nПРОВЕРЬ СЕБЯ\n1. Почему угарный газ особенно опасен по сравнению с другими токсичными веществами?\n2. Какие ранние признаки отравления угарным газом легко спутать с обычным недомоганием?\n3. Что является первым и обязательным действием при подозрении на отравление угарным газом?\n4. Как обеспечить собственную безопасность спасателя при таком отравлении?\n5. Какие меры профилактики снижают риск отравления угарным газом?'],
['Анафилактический шок и аллергические реакции','ЧТО ТАКОЕ АНАФИЛАКТИЧЕСКИЙ ШОК\nТяжёлая, стремительно развивающаяся аллергическая реакция всего организма на аллерген (укус насекомого, пищевой продукт, лекарство) — способна привести к смерти в течение минут из-за отёка дыхательных путей и резкого падения артериального давления, что делает её одним из немногих состояний в первой помощи, где счёт идёт на минуты в буквальном смысле.\n\nПРИЗНАКИ АНАФИЛАКТИЧЕСКОГО ШОКА\nВнезапная сыпь и зуд по всему телу, отёк лица, губ, языка, затруднённое дыхание, свистящее дыхание, головокружение, резкое падение давления, потеря сознания. Развивается обычно в течение минут после контакта с аллергеном.\n\nПЕРВОЕ ДЕЙСТВИЕ: АВТОИНЪЕКТОР ЭПИНЕФРИНА\nЕсли у пострадавшего есть с собой автоинъектор адреналина (эпипен, часто носят люди с известной тяжёлой аллергией) — немедленное введение в наружную поверхность бедра через одежду, согласно инструкции устройства; это единственное средство, способное быстро остановить развитие шока до приезда скорой.\n\nДЕЙСТВИЯ ПРИ ОТСУТСТВИИ АВТОИНЪЕКТОРА\nНемедленный вызов скорой с чётким указанием на подозрение анафилактического шока, придание пострадавшему положения лёжа с приподнятыми ногами (если нет затруднения дыхания — тогда полусидя), контроль дыхания и готовность к реанимации при остановке дыхания или сердца.\n\nБОЛЕЕ ЛЁГКИЕ АЛЛЕРГИЧЕСКИЕ РЕАКЦИИ\nЛокальная сыпь, зуд, небольшой отёк без затруднения дыхания — не требуют экстренных мер, но требуют наблюдения за развитием, так как реакция способна прогрессировать до анафилаксии в течение короткого времени, особенно при повторном контакте с аллергеном.\n\nПОВТОРНАЯ РЕАКЦИЯ ПОСЛЕ УЛУЧШЕНИЯ (ДВУХФАЗНАЯ АНАФИЛАКСИЯ)\nУ части пострадавших симптомы способны вернуться через несколько часов после первичного улучшения даже после введения адреналина — поэтому наблюдение и медицинская помощь необходимы даже при видимом быстром улучшении состояния.\n\nТИПИЧНЫЕ ОШИБКИ\nПромедление с использованием автоинъектора при явных признаках анафилаксии; отказ от вызова скорой после улучшения состояния из-за риска двухфазной реакции; недооценка лёгкой аллергической реакции без наблюдения за её развитием.\n\nПРОВЕРЬ СЕБЯ\n1. Чем анафилактический шок отличается от обычной аллергической реакции?\n2. Какие признаки указывают на развитие анафилактического шока?\n3. Как правильно использовать автоинъектор адреналина?\n4. Что делать при подозрении на анафилаксию без автоинъектора?\n5. Что такое двухфазная анафилаксия и почему она важна для дальнейшего наблюдения?'],
['Судорожный приступ и потеря сознания','ЧТО ПРОИСХОДИТ ПРИ СУДОРОЖНОМ ПРИСТУПЕ\nНепроизвольные мышечные сокращения, часто с потерей сознания, вызванные эпилепсией, высокой температурой (у детей), травмой головы или другими причинами — сам приступ обычно не опасен напрямую, основная задача первой помощи — предотвратить травмы во время него.\n\nГЛАВНЫЙ ПРИНЦИП: ЗАЩИТА, А НЕ СДЕРЖИВАНИЕ\nУбрать предметы, о которые пострадавший может удариться, подложить что-то мягкое под голову, НЕ пытаться удерживать судорожные движения силой (не приводит к остановке приступа и способно причинить травму), НЕ пытаться вставить что-либо в рот (устаревшее и опасное представление — риск травмы зубов и обструкции дыхательных путей).\n\nПОСЛЕ ОКОНЧАНИЯ СУДОРОГ\nПеревести в восстановительное положение (изученное ранее в программе), поскольку после приступа часто сохраняется угнетённое сознание и риск западения языка или аспирации при возможной рвоте — оставаться рядом до полного восстановления ясности сознания.\n\nКОГДА ВЫЗЫВАТЬ СКОРУЮ ПРИ СУДОРОГАХ\nПриступ длится дольше 5 минут, повторяется без восстановления сознания между приступами, первый приступ в жизни человека, приступ у беременной, травма во время приступа, судороги при высокой температуре у ребёнка младше определённого возраста — во всех этих случаях вызов обязателен.\n\nПОТЕРЯ СОЗНАНИЯ БЕЗ СУДОРОГ: ОБМОРОК\nКратковременная потеря сознания из-за временного снижения кровотока к мозгу (переутомление, духота, испуг, резкое вставание) — уложить на спину, приподнять ноги, обеспечить приток воздуха, обычно сознание восстанавливается в течение минуты.\n\nКОГДА ОБМОРОК ТРЕБУЕТ ВНИМАНИЯ КАК СЕРЬЁЗНЫЙ СИМПТОМ\nПотеря сознания дольше минуты, повторные обмороки, обморок с травмой при падении, сопутствующая боль в груди или нарушение сердечного ритма — эти признаки отличают простой обморок от возможного проявления более серьёзной проблемы, требующей обследования.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка удержать судорожные движения силой; попытка вставить что-либо в рот во время приступа; оставление пострадавшего без присмотра сразу после прекращения судорог; путаница между простым обмороком и состоянием, требующим вызова скорой.\n\nПРОВЕРЬ СЕБЯ\n1. В чём заключается главный принцип помощи во время судорожного приступа?\n2. Почему нельзя удерживать судорожные движения силой или вставлять предметы в рот?\n3. Что нужно сделать сразу после окончания судорог?\n4. В каких случаях судорожный приступ требует обязательного вызова скорой?\n5. Чем простой обморок отличается от состояния, требующего срочного обследования?'],
['Импровизированные средства остановки кровотечения','МЕСТО ЭТОЙ ТЕМЫ В КУРСЕ\nТема "Импровизированный жгут и давящая повязка" ранее в программе разбирала конкретную технику наложения жгута и повязки из подручных материалов. Здесь рассматривается более широкий вопрос: как действовать при остановке кровотечения, когда нет вообще ничего похожего на медицинские материалы — ни бинта, ни чистой ткани.\n\nПРИНЦИП: ЛЮБАЯ ТКАНЬ ЛУЧШЕ, ЧЕМ НИЧЕГО\nПри отсутствии стерильных материалов для прямого давления используется самая чистая доступная ткань — часть одежды (предпочтительно из натуральных волокон, х/б), даже не идеально чистая. Риск инфицирования — отложенная угроза, кровопотеря — немедленная, поэтому в этой иерархии приоритетов остановка крови важнее стерильности.\n\nИСПОЛЬЗОВАНИЕ ПРИРОДНЫХ МАТЕРИАЛОВ ДЛЯ ДАВЛЕНИЯ\nПри полном отсутствии ткани — плотно скомканные чистые листья широколиственных растений, мох (традиционно применялся как природный кровоостанавливающий и антисептический материал), любой относительно чистый впитывающий материал под рукой.\n\nПРЯМОЕ ДАВЛЕНИЕ РУКОЙ КАК УНИВЕРСАЛЬНЫЙ ПЕРВЫЙ ШАГ\nЕсли совсем ничего нет под рукой — прямое давление ладонью (по возможности через любую преграду, включая полиэтилен пакета) на рану — начинать нужно немедленно, не тратя время на поиск идеального материала, который может не найтись вовсе.\n\nТОЧКИ ПРИЖАТИЯ АРТЕРИЙ КАК ДОПОЛНИТЕЛЬНЫЙ ПРИЁМ\nПри недоступности жгута — пальцевое прижатие крупной артерии выше раны к кости (плечевая, бедренная артерия) способно временно уменьшить кровопотерю, но требует непрерывного физического усилия и не заменяет жгут при длительном ожидании помощи.\n\nИСПОЛЬЗОВАНИЕ СОБСТВЕННОЙ ОДЕЖДЫ КАК ИСТОЧНИКА ВСЕХ МАТЕРИАЛОВ\nФутболка разрывается на полосы: часть — на прямое давление, часть — на фиксирующую повязку, часть, при необходимости, — на импровизированный жгут; ремень от брюк — как основа для жгута с рычагом из любой найденной палки.\n\nТИПИЧНЫЕ ОШИБКИ\nТрата драгоценного времени на поиск "правильного" материала при сильном кровотечении; отказ от подручных средств из соображений негигиеничности при явной угрозе жизни; забывание о точках прижатия артерий как временной мере.\n\nПРОВЕРЬ СЕБЯ\n1. Почему при отсутствии стерильных материалов приоритет отдаётся остановке крови, а не чистоте?\n2. Какие природные материалы можно использовать для остановки кровотечения?\n3. Что делать, если совсем ничего нет под рукой, кроме собственных рук?\n4. Как использовать точки прижатия артерий и в чём их ограничение?\n5. Как можно использовать одну и ту же одежду для нескольких задач остановки кровотечения?'],
['Импровизированная иммобилизация и шины','МЕСТО ЭТОЙ ТЕМЫ В КУРСЕ\nРанее программа рассматривала изготовление шины из подручных жёстких предметов (доски, палки). Здесь рассматривается ситуация ещё более скудных ресурсов — когда нет даже подходящего жёсткого предмета, а также дополнительные методы иммобилизации, не связанные с классической шиной.\n\nИММОБИЛИЗАЦИЯ БЕЗ ЖЁСТКОГО ПРЕДМЕТА: ИСПОЛЬЗОВАНИЕ ТЕЛА\n"Нога к ноге" для нижней конечности и фиксация руки к туловищу (уже упомянутые ранее принципы) остаются основным методом при полном отсутствии любых жёстких предметов вокруг — тело человека само по себе служит "шиной".\n\nКОСЫНОЧНАЯ ПОВЯЗКА ИЗ ЛЮБОЙ ТКАНИ\nКвадратный кусок ткани (рубашка, шарф, любая одежда), сложенный по диагонали — универсальный способ подвесить и зафиксировать повреждённую руку в согнутом положении, снимая нагрузку с плеча и предплечья без каких-либо специальных материалов.\n\nИСПОЛЬЗОВАНИЕ ПРИРОДНЫХ ЖЁСТКИХ МАТЕРИАЛОВ ВНЕ ГОРОДА\nПрямые ветки достаточной толщины, куски коры плотных пород дерева, camping-снаряжение (треккинговые палки, вёсла) — в условиях природы или похода почти всегда находится что-то, способное послужить основой шины, если целенаправленно осмотреть окружение.\n\nИММОБИЛИЗАЦИЯ ПАЛЬЦЕВ И КИСТИ БЕЗ МАТЕРИАЛОВ\nПовреждённый палец руки можно зафиксировать, примотав к соседнему здоровому пальцу любой полоской ткани — простой и эффективный метод при травмах пальцев, не требующий отдельной шины.\n\nПРИОРИТИЗАЦИЯ ПРИ НЕСКОЛЬКИХ ТРАВМАХ И МИНИМУМЕ РЕСУРСОВ\nЕсли материалов на всё не хватает, в первую очередь иммобилизируются травмы, представляющие наибольший риск при движении (крупные кости, суставы, подозрение на травму позвоночника) — менее значимые травмы (палец, ушиб) можно временно оставить без формальной иммобилизации.\n\nТИПИЧНЫЕ ОШИБКИ\nОтказ от иммобилизации при отсутствии "правильных" материалов вместо использования тела как опоры; игнорирование простых решений вроде фиксации пальца к пальцу; распределение скудных ресурсов на менее приоритетные травмы в ущерб более серьёзным.\n\nПРОВЕРЬ СЕБЯ\n1. Как иммобилизировать конечность при полном отсутствии жёстких предметов?\n2. Как сделать косыночную повязку и для чего она нужна?\n3. Какие природные материалы подойдут для шины вне города?\n4. Как иммобилизировать повреждённый палец без специальных материалов?\n5. Как расставлять приоритеты при иммобилизации, если ресурсов на всё не хватает?'],
['Импровизированная защита от холода и ожогов','ЗАЩИТА ОТ ХОЛОДА БЕЗ СПЕЦИАЛЬНОГО СНАРЯЖЕНИЯ\nПринцип многослойности из подручных материалов: газеты и бумага между слоями одежды (создают воздушную прослойку, удерживающую тепло), полиэтиленовые пакеты как ветрозащитный внешний слой, любые дополнительные ткани, обёрнутые вокруг конечностей, особенно стоп и кистей, которые мёрзнут в первую очередь.\n\nИЗОЛЯЦИЯ ОТ ХОЛОДНОЙ ПОВЕРХНОСТИ\nКонтакт с холодной землёй или снегом отбирает тепло тела быстрее, чем холодный воздух — любой материал, подложенный под пострадавшего (ветки, сухая листва, рюкзак, одежда), значительно снижает потерю тепла и является приоритетным действием при подозрении на переохлаждение вне помещения.\n\nИМПРОВИЗИРОВАННОЕ УКРЫТИЕ ОТ ВЕТРА\nВетер резко усиливает эффективное охлаждение тела даже при небольшом морозе (эффект ветро-холода) — любая естественная или временная преграда (стена, автомобиль, наспех сооружённый навес из веток и ткани) существенно снижает эту опасность.\n\nЗАЩИТА ОБОЖЖЁННОЙ ПОВЕРХНОСТИ БЕЗ СТЕРИЛЬНЫХ МАТЕРИАЛОВ\nПосле охлаждения ожога водой (см. тему термических ожогов) при отсутствии стерильной неприлипающей повязки — чистая х/б ткань, свободно наложенная без давления; полиэтиленовая плёнка (пищевая или обычный чистый пакет) как временный барьер от загрязнения, если нет вообще никакой ткани.\n\nОБЩИЙ ПРИНЦИП ДЛЯ ОБОИХ СЛУЧАЕВ: НЕ ДОПУСТИТЬ УХУДШЕНИЯ, А НЕ ВЫЛЕЧИТЬ\nИмпровизированные средства при холоде и ожогах решают задачу "не дать состоянию ухудшиться до прибытия помощи", а не заменяют полноценное лечение — важно не переоценивать их эффективность и не откладывать вызов помощи, полагаясь на подручные меры.\n\nИСПОЛЬЗОВАНИЕ ОГНЯ КАК ИСТОЧНИКА ТЕПЛА\nПри наличии возможности развести костёр — источник тепла для профилактики и лечения переохлаждения, но требует осторожности при пострадавшем с ослабленным сознанием (риск дополнительного ожога при слишком близком расположении).\n\nТИПИЧНЫЕ ОШИБКИ\nИгнорирование изоляции от холодной земли, считая важным только укрытие от ветра и воздуха; наложение полиэтилена непосредственно на открытую рану без ткани между ними; переоценка импровизированных средств как полноценной замены медицинской помощи.\n\nПРОВЕРЬ СЕБЯ\n1. Как обеспечить многослойную защиту от холода из подручных материалов?\n2. Почему изоляция от холодной поверхности важна не меньше защиты от ветра?\n3. Чем можно временно защитить ожоговую поверхность без стерильных материалов?\n4. В чём общий принцип импровизированных средств при холоде и ожогах?\n5. На что обратить внимание при использовании костра рядом с пострадавшим?'],
['Действия при полном отсутствии подручных средств','КОГДА НЕТ АБСОЛЮТНО НИЧЕГО\nКрайний случай программы: ни аптечки, ни ткани, ни жёстких предметов, ни укрытия — только руки, тело и знания. Эта тема сводит воедино, что остаётся в распоряжении в такой ситуации и в каком порядке действовать.\n\nИЕРАРХИЯ ДЕЙСТВИЙ БЕЗ КАКИХ-ЛИБО СРЕДСТВ\n1) Обеспечение проходимости дыхательных путей и оценка дыхания (ничего, кроме рук, не требуется); 2) прямое давление рукой на кровотечение; 3) удержание тела в тепле собственным телом (обнять пострадавшего, если позволяет ситуация); 4) поддержание сознания разговором и контролем состояния; 5) как можно более быстрое привлечение помощи (крик, поиск людей, движение к людному месту, если пострадавший не может ждать в одиночестве).\n\nСОБСТВЕННОЕ ТЕЛО КАК ЕДИНСТВЕННЫЙ ДОСТУПНЫЙ ИНСТРУМЕНТ\nПрямое давление ладонью или коленом (если требуется освободить руки) на кровотечение; собственное тело как источник тепла при обнимании пострадавшего в положении, минимизирующем контакт с холодной поверхностью; голос как инструмент поддержания сознания и контроля состояния.\n\nПРИНЦИП РАЗДЕЛЕНИЯ ЗАДАЧ ПРИ НЕСКОЛЬКИХ СПАСАТЕЛЯХ\nЕсли рядом есть другие люди — один продолжает прямое давление на рану, другой немедленно идёт или бежит за помощью, третий (при наличии) поддерживает пострадавшего в сознании — распределение ролей критично важно, когда индивидуально ни у кого нет специальных средств.\n\nКОГДА ОСТАВИТЬ ПОСТРАДАВШЕГО, ЧТОБЫ ПОЗВАТЬ НА ПОМОЩЬ\nЕсли спасатель один, а состояние пострадавшего стабильно (кровотечение контролируется прямым давлением, сознание сохранено) — кратковременный уход для вызова помощи оправдан; при нестабильном состоянии (продолжающееся кровотечение без возможности прижатия, угасающее сознание) — приоритет отдаётся непрерывному нахождению рядом и попыткам привлечь внимание криком.\n\nЗНАНИЕ КАК ГЛАВНЫЙ РЕСУРС В ЭТОЙ СИТУАЦИИ\nДанная тема — практическое напоминание того, ради чего был пройден весь курс: при отсутствии любых материальных средств именно знание алгоритмов (ABC, признаки состояний, приоритеты действий), пройденных в предыдущих модулях, остаётся единственным работающим инструментом первой помощи.\n\nТИПИЧНЫЕ ОШИБКИ\nРастерянность и бездействие при отсутствии привычных средств вместо использования тела и знаний; уход за помощью при нестабильном состоянии пострадавшего, когда важнее оставаться рядом; отсутствие распределения ролей при наличии нескольких помощников.\n\nПРОВЕРЬ СЕБЯ\n1. Какова иерархия действий при полном отсутствии каких-либо средств?\n2. Как использовать собственное тело для остановки кровотечения и согревания?\n3. Как распределить роли между несколькими спасателями без специальных средств?\n4. Когда оправдан кратковременный уход за помощью, а когда нет?\n5. Какой ресурс остаётся главным при отсутствии абсолютно всех материальных средств?'],
['Состав базовой аптечки и назначение компонентов','ЗАЧЕМ НУЖНА ПРОДУМАННАЯ, А НЕ СЛУЧАЙНАЯ АПТЕЧКА\nГотовые аптечки часто содержат случайный набор компонентов без понимания их применения — цель этой темы дать осознанный список, где каждый элемент имеет чёткое назначение, соответствующее темам, уже пройденным в курсе (кровотечения, переломы, ожоги, аллергия).\n\nБАЗОВЫЙ УРОВЕНЬ: КОМПОНЕНТЫ ДЛЯ КРОВОТЕЧЕНИЙ И РАН\nСтерильные салфетки и бинты разных размеров, кровоостанавливающий жгут (табельный, типа CAT), гемостатический бинт, лейкопластырь, антисептик для обработки краёв раны (не самой раны при сильном кровотечении) — прямое соответствие модулю "Кровотечения и раны".\n\nСРЕДНИЙ УРОВЕНЬ: КОМПОНЕНТЫ ДЛЯ ТРАВМ И ОЖОГОВ\nЭластичный бинт, шина (пневматическая или лестничная), охлаждающий пакет (для растяжений и ожогов при отсутствии проточной воды), специальная ожоговая повязка — соответствует модулям травм опорно-двигательного аппарата и ожогов.\n\nРАСШИРЕННЫЙ УРОВЕНЬ: КОМПОНЕНТЫ ДЛЯ ОСТРЫХ СОСТОЯНИЙ\nАвтоинъектор адреналина (по рецепту при известной аллергии), маска для проведения искусственного дыхания (барьерное средство), термоодеяло (для гипотермии и шока), регидратационные солевые растворы — соответствует модулям острых состояний, реанимации и холодовых поражений.\n\nИНСТРУМЕНТЫ И ВСПОМОГАТЕЛЬНЫЕ СРЕДСТВА\nНожницы для разрезания одежды, перчатки (защита спасателя от контакта с кровью), пинцет, фонарик, маркер или бумага для записи времени наложения жгута — не лечебные, но необходимые для эффективного применения остальных компонентов.\n\nПРИНЦИП СООТВЕТСТВИЯ АПТЕЧКИ РЕАЛЬНЫМ РИСКАМ\nСостав аптечки для дома отличается от автомобильной, туристической или для длительного похода — количество и виды компонентов должны соответствовать вероятным сценариям применения, а не быть одинаковым "стандартным набором" для любой ситуации.\n\nТИПИЧНЫЕ ОШИБКИ\nПокупка готовой аптечки без понимания назначения компонентов; отсутствие перчаток, из-за чего спасатель контактирует с кровью пострадавшего напрямую; аптечка без адаптации под конкретный контекст использования (дом, авто, поход).\n\nПРОВЕРЬ СЕБЯ\n1. Почему важно понимать назначение каждого компонента аптечки, а не просто иметь готовый набор?\n2. Какие компоненты соответствуют модулю "Кровотечения и раны"?\n3. Какие компоненты нужны для острых состояний вроде анафилаксии?\n4. Зачем в аптечке нужны перчатки и маркер, если это не лечебные средства?\n5. Почему состав аптечки должен зависеть от контекста использования?'],
['Виды перевязочных материалов и их выбор','ЗАЧЕМ РАЗБИРАТЬСЯ В ТИПАХ ПЕРЕВЯЗОЧНЫХ МАТЕРИАЛОВ\nРазные материалы решают разные задачи — использование неподходящего типа повязки способно замедлить заживление, приклеиться к ране или не обеспечить нужное давление при кровотечении. Осознанный выбор материала — часть эффективной первой помощи, а не просто "любой бинт подойдёт".\n\nСТЕРИЛЬНЫЕ САЛФЕТКИ\nПервый слой, накладываемый непосредственно на рану — стерильность снижает риск инфицирования, размер выбирается по площади раны, для сильного кровотечения используются несколько салфеток без снятия предыдущей при промокании.\n\nБИНТЫ: МАРЛЕВЫЕ И ЭЛАСТИЧНЫЕ\nМарлевый бинт — для фиксации стерильной салфетки и создания давящей повязки на раны; эластичный бинт — для растяжений, вывихов и фиксации шин, обеспечивает более равномерное распределение давления при многократном использовании.\n\nНЕПРИЛИПАЮЩИЕ ПОВЯЗКИ ДЛЯ ОЖОГОВ\nСпециальное покрытие, не прилипающее к ожоговой поверхности при смене повязки (в отличие от обычной марли, которая присыхает к экссудату раны) — критично важно для ожогов, где смена обычной повязки причиняет дополнительную травму и боль.\n\nГЕМОСТАТИЧЕСКИЕ ПОВЯЗКИ И ИХ ОТЛИЧИЕ ОТ ОБЫЧНЫХ\nПропитаны веществом, ускоряющим свёртывание крови (каолин, хитозан) — применяются при сильных кровотечениях, не останавливающихся обычным прямым давлением, что уже упоминалось в теме остановки кровотечения аптечными средствами.\n\nПЛАСТЫРИ: ВИДЫ И НАЗНАЧЕНИЕ\nОбычный лейкопластырь — для мелких ссадин и порезов; пластырь-бабочка — для стягивания краёв неглубокой раны без наложения швов; водостойкий пластырь — для ран в условиях контакта с водой.\n\nТИПИЧНЫЕ ОШИБКИ\nИспользование обычной марли на ожоговой ране, приводящее к её прилипанию; выбор пластыря-бабочки для глубокой раны, которая нуждается в швах; экономия материала при сильном кровотечении вместо использования нескольких слоёв.\n\nПРОВЕРЬ СЕБЯ\n1. Почему выбор перевязочного материала влияет на исход оказания помощи?\n2. Чем марлевый бинт отличается от эластичного по назначению?\n3. Зачем нужны специальные неприлипающие повязки для ожогов?\n4. Как работают гемостатические повязки?\n5. Для чего предназначен пластырь-бабочка и когда его использование неуместно?'],
['Медикаменты первой помощи: что и когда','ГРАНИЦА МЕЖДУ ПЕРВОЙ ПОМОЩЬЮ И ЛЕЧЕНИЕМ\nПервая помощь не подразумевает постановку диагноза или назначение лечения — медикаменты в аптечке первой помощи ограничены средствами для облегчения острого состояния до прибытия медицинской помощи, а не для терапии заболевания.\n\nОБЕЗБОЛИВАЮЩИЕ И ЖАРОПОНИЖАЮЩИЕ ОБЩЕГО ПРИМЕНЕНИЯ\nСтандартные безрецептурные препараты для снижения боли и температуры — применяются при отсутствии противопоказаний (аллергия, взаимодействие с другими принимаемыми лекарствами), важно спрашивать пострадавшего об аллергиях и принимаемых препаратах перед предложением любого медикамента.\n\nАНТИГИСТАМИННЫЕ ПРЕПАРАТЫ\nПрименяются при лёгких аллергических реакциях (не заменяют автоинъектор адреналина при анафилаксии, рассмотренной ранее) — снижают зуд и локальный отёк при контактной аллергии или укусах насекомых без признаков системной реакции.\n\nСРЕДСТВА ДЛЯ ОБРАБОТКИ РАН\nАнтисептические растворы для очистки кожи вокруг раны (не заливаются в глубокую рану или на сильно кровоточащую поверхность), средства от ожогов на основе пантенола для лёгких термических ожогов первой степени после охлаждения.\n\nПРИНЦИП: НЕ ДАВАТЬ МЕДИКАМЕНТЫ БЕЗ ДОСТАТОЧНОЙ ИНФОРМАЦИИ\nНе предлагать никакие препараты, если пострадавший без сознания, если есть подозрение на аллергию на конкретное вещество, если неизвестно взаимодействие с уже принятыми пострадавшим лекарствами или алкоголем — в этих случаях медикамент способен нанести больше вреда, чем отсутствие лечения до приезда медиков.\n\nХРАНЕНИЕ И СРОКИ ГОДНОСТИ МЕДИКАМЕНТОВ\nМедикаменты с истёкшим сроком годности теряют эффективность, а в некоторых случаях становятся небезопасными — регулярная проверка сроков годности является частью ответственного владения аптечкой, что подробно рассматривается в следующей теме.\n\nТИПИЧНЫЕ ОШИБКИ\nДача обезболивающего без выяснения аллергий пострадавшего; попытка "лечить" антигистаминным препаратом настоящую анафилаксию вместо адреналина; предложение медикаментов пострадавшему без сознания; использование медикаментов с истёкшим сроком годности.\n\nПРОВЕРЬ СЕБЯ\n1. Чем первая помощь принципиально отличается от лечения с точки зрения медикаментов?\n2. Что нужно уточнить перед тем, как предложить пострадавшему обезболивающее?\n3. Могут ли антигистаминные препараты заменить адреналин при анафилаксии?\n4. В каких случаях нельзя давать медикаменты пострадавшему вообще?\n5. Почему важно следить за сроком годности медикаментов в аптечке?'],
['Проверка и обновление аптечки','АПТЕЧКА — НЕ ОДНОРАЗОВАЯ ПОКУПКА\nСобранная один раз аптечка со временем теряет актуальность: расходуются использованные материалы, истекают сроки годности медикаментов, меняются потребности (появление ребёнка в семье, новое хроническое заболевание) — регулярная проверка так же важна, как и первоначальная комплектация.\n\nРЕКОМЕНДУЕМАЯ ПЕРИОДИЧНОСТЬ ПРОВЕРКИ\nПолная проверка состава и сроков годности не реже раза в 6-12 месяцев, а также сразу после любого использования аптечки — компонент, израсходованный в момент оказания помощи, должен быть немедленно восполнен, а не оставлен "на потом".\n\nЧТО ПРОВЕРЯТЬ ПРИ РЕВИЗИИ АПТЕЧКИ\nСроки годности медикаментов и стерильных материалов (стерильность гарантируется производителем только до определённой даты), целостность упаковок (нарушенная упаковка стерильного материала делает его нестерильным), состояние жгута и других резиновых/эластичных компонентов (со временем теряют эластичность).\n\nАДАПТАЦИЯ СОСТАВА ПОД ИЗМЕНИВШИЕСЯ ОБСТОЯТЕЛЬСТВА\nПоявление в семье человека с известной тяжёлой аллергией — добавление автоинъектора адреналина; переезд в регион с холодным климатом — усиление блока средств от переохлаждения; освоение вождения — комплектация автомобильной аптечки отдельно от домашней.\n\nВЕДЕНИЕ ПРОСТОГО УЧЁТА\nНебольшой список содержимого с датами истечения срока годности, прикреплённый к самой аптечке или хранящийся отдельно — простой инструмент, исключающий необходимость каждый раз проверять всё содержимое полностью.\n\nСВЯЗЬ С ОСТАЛЬНЫМ КУРСОМ: АПТЕЧКА КАК ЖИВОЙ ИНСТРУМЕНТ\nЭтот блок программы, посвящённый аптечке, логически завершает переход от теоретического знания (что делать) к практической готовности (чем это делать) — осознанно собранная и регулярно обновляемая аптечка — необходимое дополнение к знаниям, полученным в предыдущих модулях.\n\nТИПИЧНЫЕ ОШИБКИ\nПолное отсутствие периодической проверки аптечки годами; невосполнение израсходованных материалов сразу после использования; игнорирование изменившихся семейных обстоятельств при комплектации; хранение аптечки с истёкшими медикаментами "на всякий случай".\n\nПРОВЕРЬ СЕБЯ\n1. Почему аптечку нельзя считать разовой покупкой?\n2. С какой периодичностью рекомендуется проверять аптечку?\n3. Что именно проверяется при ревизии аптечки?\n4. Приведите пример адаптации состава аптечки под изменившиеся обстоятельства.\n5. Зачем вести простой учёт содержимого аптечки?'],
['Поведение и эвакуация при пожаре','ГЛАВНЫЙ ПРИНЦИП: СНАЧАЛА ВЫХОД, ПОТОМ ВСЁ ОСТАЛЬНОЕ\nПри обнаружении пожара первоочередное действие — немедленная эвакуация людей, а не попытки потушить огонь или спасти имущество, за исключением случаев, когда возгорание совсем небольшое и явно контролируется имеющимися средствами тушения.\n\nДВИЖЕНИЕ В ЗАДЫМЛЁННОМ ПОМЕЩЕНИИ\nДым скапливается сверху вниз, самый чистый воздух — у пола, поэтому передвижение в задымлённом помещении осуществляется пригнувшись или ползком, прикрывая рот и нос влажной тканью, что значительно снижает риск отравления продуктами горения.\n\nПРОВЕРКА ДВЕРЕЙ ПЕРЕД ОТКРЫВАНИЕМ\nТыльной стороной ладони проверяется температура двери и дверной ручки — горячая дверь означает огонь с другой стороны, и её открывать нельзя (резкий приток кислорода вызывает вспышку пламени, известную как обратная тяга); в этом случае ищется альтернативный путь эвакуации.\n\nЕСЛИ ЭВАКУАЦИЯ НЕВОЗможна: ГЕРМЕТИЗАЦИЯ ПОМЕЩЕНИЯ\nПри невозможности покинуть помещение — плотно закрыть дверь, заткнуть щели мокрой тканью, подать сигнал о своём местонахождении (у окна, ярким предметом, криком), вызвать экстренные службы и сообщить точный этаж и местоположение.\n\nЧТО ДЕЛАТЬ, ЕСЛИ ОДЕЖДА ЗАГОРЕЛАСЬ\nКлассический алгоритм "остановись, упади, катайся" (stop, drop, roll) — остановиться (бег усиливает горение из-за притока воздуха), упасть на землю, катиться для сбивания пламени; после этого немедленное охлаждение обожжённых участков, как рассмотрено в теме термических ожогов.\n\nПОВЕДЕНИЕ ПОСЛЕ ЭВАКУАЦИИ\nОтойти на безопасное расстояние от здания, не возвращаться за вещами или домашними животными до разрешения пожарных служб, сообщить прибывшим службам о людях, оставшихся внутри, если такая информация есть.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытки тушить крупный пожар подручными средствами вместо немедленной эвакуации; открывание горячей двери без проверки; передвижение в полный рост в задымлённом помещении; бег при загоревшейся одежде вместо остановки и падения на землю.\n\nПРОВЕРЬ СЕБЯ\n1. Какое действие является первоочередным при обнаружении пожара?\n2. Как правильно передвигаться в задымлённом помещении и почему именно так?\n3. Как проверить дверь перед открыванием и что означает горячая дверь?\n4. Опишите алгоритм действий, если загорелась одежда.\n5. Что делать, если эвакуация из помещения невозможна?'],
['Отравление продуктами горения','ЧЕМ ОПАСНЫ ПРОДУКТЫ ГОРЕНИЯ ПОМИМО ОГНЯ\nПри пожаре гибель людей чаще вызвана не самим огнём, а вдыханием токсичных продуктов горения — угарного газа (см. отдельную тему ранее в курсе) и других токсичных соединений, образующихся при горении синтетических материалов (пластик, поролон, современная мебель).\n\nПРИЗНАКИ ОТРАВЛЕНИЯ ПРОДУКТАМИ ГОРЕНИЯ\nКашель, затруднённое дыхание, охриплость голоса, головная боль, спутанность сознания, копоть вокруг носа и рта — эти признаки требуют немедленной оценки состояния дыхательных путей и вызова скорой помощи независимо от видимых внешних ожогов.\n\nПЕРВАЯ ПОМОЩЬ ПОСЛЕ ВЫВОДА ИЗ ЗАДЫМЛЁННОЙ ЗОНЫ\nВывести на свежий воздух, обеспечить положение полусидя, если позволяет дыхание (облегчает работу лёгких), контроль дыхания и готовность к реанимации при его остановке — все действия аналогичны первой помощи при отравлении угарным газом, но здесь добавляется учёт возможного повреждения дыхательных путей.\n\nОСОБАЯ ОПАСНОСТЬ СИНТЕТИЧЕСКИХ МАТЕРИАЛОВ\nГорение современных синтетических материалов (мебельная обивка, пластиковая отделка, утеплители) выделяет большее количество и более токсичные соединения, чем горение натуральных материалов — это одна из причин, почему современные пожары в помещениях развиваются и становятся смертельно опасными быстрее, чем десятилетия назад.\n\nЗАДЕРЖКА ПРОЯВЛЕНИЯ ТЯЖЁЛЫХ ПОСЛЕДСТВИЙ\nНекоторые повреждения дыхательных путей и лёгких от токсичных продуктов горения проявляются не сразу, а через несколько часов после воздействия — поэтому любой человек, находившийся в задымлённом помещении при пожаре, должен быть осмотрен медиками, даже при отсутствии выраженных симптомов сразу после эвакуации.\n\nСВЯЗЬ С ТЕМОЙ ОТРАВЛЕНИЯ УГАРНЫМ ГАЗОМ\nУгарный газ — лишь одна из множества токсичных составляющих дыма при пожаре; принципы первой помощи (вывод на свежий воздух, контроль дыхания, обязательный вызов скорой) переносятся из той темы и дополняются вниманием к возможному термическому повреждению дыхательных путей.\n\nТИПИЧНЫЕ ОШИБКИ\nНедооценка состояния человека, вышедшего из задымлённого помещения без видимых внешних повреждений; отказ от вызова скорой при отсутствии немедленных симптомов; незнание о повышенной токсичности горения современных синтетических материалов.\n\nПРОВЕРЬ СЕБЯ\n1. Почему гибель людей при пожаре чаще связана не с огнём напрямую, а с продуктами горения?\n2. Какие признаки указывают на отравление продуктами горения?\n3. Какая первая помощь оказывается после вывода пострадавшего из задымлённой зоны?\n4. Чем опасно горение синтетических материалов по сравнению с натуральными?\n5. Почему нужно наблюдение медиков, даже если симптомы не проявились сразу?'],
['Ожоги дыхательных путей','ОСОБЫЙ И ОПАСНЫЙ ТИП ТРАВМЫ ПРИ ПОЖАРЕ\nВдыхание раскалённого воздуха или пара повреждает слизистую дыхательных путей изнутри — в отличие от кожного ожога, эта травма не видна снаружи, но способна привести к отёку и полному перекрытию дыхательных путей в течение короткого времени после воздействия.\n\nПРИЗНАКИ ОЖОГА ДЫХАТЕЛЬНЫХ ПУТЕЙ\nОпалённые волосы в носу, копоть на языке и в ротовой полости, осиплость или потеря голоса, свистящее или затруднённое дыхание, ожоги лица и шеи — сочетание этих признаков с фактом нахождения в задымлённом или горячем помещении требует немедленного вызова скорой, даже при отсутствии выраженной одышки в моменте.\n\nОПАСНОСТЬ НАРАСТАЮЩЕГО ОТЁКА\nОтёк слизистой дыхательных путей после термического повреждения развивается постепенно и способен резко ухудшить состояние через 30-60 минут после травмы — пострадавший с подозрением на ожог дыхательных путей нуждается в непрерывном наблюдении даже при первоначально нормальном дыхании.\n\nПОЛОЖЕНИЕ ТЕЛА ДЛЯ ОБЛЕГЧЕНИЯ ДЫХАНИЯ\nПолусидя с приподнятой верхней частью тела, если пострадавший в сознании и это не противоречит другим травмам (например, подозрению на травму позвоночника) — облегчает работу дыхательных мышц при частично суженных дыхательных путях.\n\nЧТО НЕЛЬЗЯ ДЕЛАТЬ ПРИ ПОДОЗРЕНИИ НА ОЖОГ ДЫХАТЕЛЬНЫХ ПУТЕЙ\nДавать пить или есть (риск дополнительного повреждения и аспирации при возможной рвоте), укладывать горизонтально без необходимости, откладывать вызов скорой при кажущемся нормальном дыхании сразу после травмы, недооценивать травму при отсутствии видимых ожогов кожи лица.\n\nГОТОВНОСТЬ К УХУДШЕНИЮ СОСТОЯНИЯ\nПри появлении нарастающего затруднения дыхания, синюшности губ, невозможности говорить — состояние расценивается как критическое, требующее максимально быстрой медицинской помощи, поскольку отёк дыхательных путей способен полностью перекрыть их проходимость.\n\nТИПИЧНЫЕ ОШИБКИ\nНедооценка ожога дыхательных путей из-за отсутствия видимых кожных ожогов; попытка напоить пострадавшего с подозрением на такую травму; промедление с вызовом скорой при первоначально нормальном дыхании; укладывание пострадавшего горизонтально, ухудшающее дыхание.\n\nПРОВЕРЬ СЕБЯ\n1. Чем ожог дыхательных путей опасен, в отличие от обычного кожного ожога?\n2. Какие признаки указывают на возможный ожог дыхательных путей?\n3. Почему отёк дыхательных путей может нарастать спустя время после травмы?\n4. Какое положение тела облегчает дыхание пострадавшего?\n5. Что категорически нельзя делать при подозрении на такую травму?'],
['Помощь пострадавшим после пожара','ЗАВЕРШАЮЩИЙ ЭТАП: ПОМОЩЬ ПОСЛЕ НЕПОСРЕДСТВЕННОЙ УГРОЗЫ\nПосле эвакуации и устранения непосредственной опасности огня требуется системная оценка состояния всех пострадавших — сочетание нескольких видов травм (ожоги, отравление продуктами горения, травмы при эвакуации, стресс) типично для пожаров и требует комплексного подхода.\n\nСОРТИРОВКА ПОСТРАДАВШИХ ПО ПРИОРИТЕТУ ПОМОЩИ\nПри пожаре с несколькими пострадавшими помощь оказывается по убыванию срочности: нарушение дыхания и признаки ожога дыхательных путей → сильное кровотечение или ожоги значительной площади → менее тяжёлые состояния — принцип аналогичен общей логике первичной оценки, изученной в начале курса.\n\nОБЪЕДИНЕНИЕ РАНЕЕ ИЗУЧЕННЫХ ТЕМ\nНа месте пожара может одновременно потребоваться помощь при ожогах (термические ожоги), при отравлении угарным газом и продуктами горения, при травмах, полученных во время эвакуации (переломы, ушибы) — эта тема иллюстрирует, что реальные ситуации редко ограничиваются одним изолированным видом травмы.\n\nПСИХОЛОГИЧЕСКОЕ СОСТОЯНИЕ ПОСТРАДАВШИХ\nПожар — сильный стрессовый фактор, вызывающий состояние, близкое к описанному в теме стрессовой реакции организма в конфликте (модуль психологической подготовки боевой системы) — растерянность, туннельное восприятие, попытки вернуться за вещами вопреки опасности требуют спокойного, но твёрдого руководства со стороны оказывающего помощь.\n\nУЧЁТ ЛЮДЕЙ И ЖИВОТНЫХ\nСистематическая проверка, все ли эвакуировались, сообщение прибывшим пожарным о возможно оставшихся внутри людях — критически важная информация, влияющая на тактику спасательной операции.\n\nДОЛГОСРОЧНОЕ НАБЛЮДЕНИЕ ПОСЛЕ ПРОИСШЕСТВИЯ\nДаже при отсутствии видимых серьёзных травм рекомендуется медицинский осмотр всех находившихся в задымлённом помещении из-за возможной отсроченной реакции на вдыхание токсичных веществ, а также, при необходимости, психологическая поддержка после травмирующего события.\n\nТИПИЧНЫЕ ОШИБКИ\nОказание помощи без сортировки по приоритету при нескольких пострадавших; фокус только на одном виде травмы без учёта сочетанных повреждений; недооценка психологического состояния пострадавших; отсутствие последующего медицинского наблюдения при видимом отсутствии травм.\n\nПРОВЕРЬ СЕБЯ\n1. Почему на месте пожара часто требуется помощь при нескольких видах травм одновременно?\n2. По какому принципу сортируются пострадавшие по приоритету помощи?\n3. Как проявляется психологическое состояние пострадавших после пожара?\n4. Почему важно систематически проверять, все ли люди эвакуированы?\n5. Зачем нужно медицинское наблюдение после пожара даже без видимых травм?'],
['Поведение при подъёме воды и эвакуации','ПРИНЦИП: ВЫСОТА ВАЖНЕЕ ВСЕГО ОСТАЛЬНОГО\nПри начале подтопления главная задача — как можно быстрее переместиться на возвышенное место (верхние этажи, крыша, возвышенность местности) и оставаться там, а не пытаться защитить имущество на нижних уровнях, где риск быть отрезанным или унесённым водой нарастает стремительно.\n\nОПАСНОСТЬ ДВИЖЕНИЯ ЧЕРЕЗ ДВИЖУЩУЮСЯ ВОДУ\nПоток воды высотой всего 15-20 см способен сбить взрослого человека с ног при достаточной скорости течения, а автомобиль может быть снесён потоком глубиной около 30 см — эти ориентиры, используемые службами гражданской обороны, показывают, что наводнение опаснее, чем интуитивно кажется по видимой глубине воды.\n\nЕСЛИ ПРИХОДИТСЯ ПЕРЕДВИГАТЬСЯ ЧЕРЕЗ ВОДУ\nИспользование прочной палки для проверки глубины и твёрдости поверхности перед каждым шагом (под водой могут быть открытые люки, ямы, обрывы), движение против течения избегается, предпочтительно движение по диагонали к берегу или возвышенности, а не напрямую против потока.\n\nЭВАКУАЦИЯ НА ТРАНСПОРТЕ ПРИ НАВОДНЕНИИ\nКатегорический отказ от попыток проехать через затопленный участок дороги — глубина под водой не поддаётся точной оценке визуально, а заглохший в воде автомобиль представляет серьёзную опасность; при внезапном подтоплении вокруг движущегося автомобиля — немедленно покинуть его и двигаться на возвышенность пешком.\n\nПОДГОТОВКА К ВОЗМОЖНОЙ ЭВАКУАЦИИ ЗАРАНЕЕ\nПри заблаговременном предупреждении о угрозе наводнения — отключение электричества и газа в помещении перед уходом (снижает риск дополнительных происшествий при контакте воды с проводкой), подготовка минимального набора документов и предметов первой необходимости.\n\nЕСЛИ ЭВАКУАЦИЯ НЕВОЗМОЖНА И ПРИХОДИТСЯ ОСТАВАТЬСЯ\nПодъём на самый высокий доступный уровень (верхний этаж, чердак, крыша), сохранение видимого сигнала для спасателей (яркая ткань, свет), экономия сил и воды при длительном ожидании помощи, поддержание связи, если это возможно.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка защитить имущество вместо немедленного ухода на возвышенность; недооценка опасности даже неглубокого быстрого потока; попытка проехать через затопленную дорогу на автомобиле; промедление с эвакуацией при заблаговременном предупреждении.\n\nПРОВЕРЬ СЕБЯ\n1. Какой принцип является главным при начале подтопления?\n2. Почему даже неглубокий поток воды представляет серьёзную опасность?\n3. Как безопасно передвигаться через воду при необходимости?\n4. Почему нельзя пытаться проехать через затопленный участок дороги?\n5. Что делать, если эвакуация невозможна и приходится оставаться на месте?'],
['Утопление и реанимация пострадавшего из воды','ОСОБЕННОСТИ СПАСЕНИЯ ИЗ ВОДЫ\nПервое правило спасения тонущего — не становиться вторым утопающим: по возможности подать тонущему любой плавучий предмет или протянуть длинный предмет (палку, ветку, одежду), не заходя в глубокую или быструю воду самому без специальной подготовки.\n\nИЗВЛЕЧЕНИЕ ПОСТРАДАВШЕГО НА СУШУ\nПри приближении к тонущему вплавь — подход сзади (снижает риск, что паникующий человек утопит спасателя, вцепившись в него), поддержка головы над водой при транспортировке к берегу, при необходимости на суше — немедленная оценка дыхания и сознания.\n\nПОЧЕМУ РЕАНИМАЦИЯ ПРИ УТОПЛЕНИИ ИМЕЕТ ОСОБЕННОСТЬ\nВ отличие от стандартного протокола сердечно-лёгочной реанимации (изученного в модуле реанимации), при утоплении первопричиной остановки сердца обычно является нехватка кислорода, а не проблема с сердцем напрямую — поэтому современные рекомендации (в отличие от устаревших) отдают приоритет пяти начальным искусственным вдохам перед началом компрессий грудной клетки.\n\nАДАПТИРОВАННЫЙ АЛГОРИТМ РЕАНИМАЦИИ ПРИ УТОПЛЕНИИ\nПять начальных искусственных вдохов → далее стандартный цикл 30 компрессий и 2 вдоха, как в обычной СЛР → продолжение до прибытия скорой или признаков жизни. Вода в лёгких при этом не откачивается специальными манипуляциями — попытки "вылить воду" (переворачивание вниз головой) не рекомендуются современными протоколами и задерживают начало реанимации.\n\nГИПОТЕРМИЯ ПРИ УТОПЛЕНИИ В ХОЛОДНОЙ ВОДЕ\nПребывание в холодной воде быстро вызывает переохлаждение (см. отдельную тему далее), которое, с одной стороны, опасно само по себе, но с другой — способно замедлить метаболизм и в редких задокументированных случаях повышает шансы на успешную реанимацию даже после длительного пребывания под водой, что является основанием не прекращать реанимационные попытки преждевременно.\n\nОБЯЗАТЕЛЬНОЕ НАБЛЮДЕНИЕ ПОСЛЕ СПАСЕНИЯ ИЗ ВОДЫ\nДаже пострадавший, который откашлялся и, казалось бы, пришёл в норму после извлечения из воды, должен быть осмотрен медиками — существует состояние отсроченного повреждения лёгких после утопления (проявляется через часы), способное развиться уже после кажущегося благополучного разрешения ситуации.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка спасти тонущего, заплыв к нему без специальной подготовки, что создаёт риск для двоих; попытки "вылить воду" из лёгких переворачиванием пострадавшего; отказ от медицинского осмотра после кажущегося полного восстановления; преждевременное прекращение реанимации из-за длительного пребывания в холодной воде.\n\nПРОВЕРЬ СЕБЯ\n1. Какое первое правило безопасности при спасении тонущего человека?\n2. Как правильно приближаться к тонущему при спасении вплавь?\n3. Чем реанимация при утоплении отличается от стандартного протокола СЛР?\n4. Опишите адаптированный алгоритм реанимации при утоплении.\n5. Почему пострадавшего после утопления нужно показать врачу, даже если он выглядит полностью восстановившимся?'],
['Переохлаждение при длительном пребывании в воде','ПОЧЕМУ ВОДА ОХЛАЖДАЕТ ГОРАЗДО БЫСТРЕЕ ВОЗДУХА\nВода отводит тепло от тела примерно в 25 раз быстрее воздуха той же температуры — переохлаждение при пребывании в воде развивается значительно быстрее, чем на суше при аналогичной температуре, что делает время нахождения в холодной воде критическим фактором выживания при наводнениях.\n\nОРИЕНТИРОВОЧНОЕ ВРЕМЯ БЕЗОПАСНОГО ПРЕБЫВАНИЯ\nЧем ниже температура воды, тем быстрее наступает опасное переохлаждение — в очень холодной воде (близкой к нулю) критическое состояние способно развиться уже за 15-30 минут, что требует максимально быстрого извлечения человека из воды при любом наводнении в холодное время года.\n\nПОЗА ВЫЖИВАНИЯ В ХОЛОДНОЙ ВОДЕ (ДО ИЗВЛЕЧЕНИЯ)\nПри невозможности немедленного извлечения — минимизация движений (интенсивные движения ускоряют теплопотерю через усиленный кровоток к конечностям), поза с прижатыми к телу руками и ногами (защита областей наибольшей теплопотери), использование любого плавучего средства для экономии сил.\n\nПЕРВАЯ ПОМОЩЬ ПОСЛЕ ИЗВЛЕЧЕНИЯ ИЗ ХОЛОДНОЙ ВОДЫ\nПринципы совпадают с общей темой обморожения и общего переохлаждения, изученной ранее: немедленное снятие мокрой одежды, постепенное согревание, минимизация резких движений пострадавшего — при утоплении в холодной воде эти меры сочетаются с контролем дыхания и готовностью к реанимации.\n\nОСОБАЯ ОСТОРОЖНОСТЬ ПРИ ПЕРЕМЕЩЕНИИ ПЕРЕОХЛАЖДЁННОГО ЧЕЛОВЕКА\nРезкое перемещение или физическая активность сильно переохлаждённого человека способны спровоцировать опасное нарушение сердечного ритма (эффект, иногда называемый "смерть от спасения") — перемещение выполняется максимально плавно и горизонтально, без резких движений.\n\nСВЯЗЬ С ПРЕДЫДУЩИМИ ТЕМАМИ КУРСА\nЭта тема прямо опирается на принципы модуля "Ожоги и холодовые поражения" (общее переохлаждение) и дополняет их спецификой водной среды — это иллюстрирует, как отдельные модули курса пересекаются в реальных сценариях стихийных бедствий.\n\nТИПИЧНЫЕ ОШИБКИ\nНедооценка скорости переохлаждения в воде по сравнению с воздухом; активные попытки плыть или двигаться, ускоряющие теплопотерю, вместо минимизации движений; резкое перемещение сильно переохлаждённого пострадавшего после извлечения из воды.\n\nПРОВЕРЬ СЕБЯ\n1. Почему вода охлаждает тело значительно быстрее воздуха?\n2. Какие факторы влияют на время безопасного пребывания в холодной воде?\n3. Какая поза рекомендуется для человека в холодной воде до извлечения?\n4. Как правильно оказывать помощь после извлечения из холодной воды?\n5. Почему резкое перемещение сильно переохлаждённого человека опасно?'],
['Помощь после эвакуации из зоны затопления','ЗАДАЧИ ПОСЛЕ ЗАВЕРШЕНИЯ НЕПОСРЕДСТВЕННОЙ ЭВАКУАЦИИ\nПосле выхода из зоны затопления возникает новый набор задач: оценка состояния здоровья эвакуированных, организация условий временного размещения, контроль за инфекционными и санитарными рисками, характерными именно для последствий наводнений.\n\nЗАГРЯЗНЕНИЕ ВОДЫ И РИСК ИНФЕКЦИЙ\nПаводковая вода часто загрязнена канализационными стоками, химическими веществами и мусором — любые раны, контактировавшие с такой водой, обрабатываются как потенциально инфицированные, требуют промывания чистой водой и медицинского наблюдения даже при небольшом размере.\n\nКОЖНЫЕ ПРОБЛЕМЫ ОТ ДЛИТЕЛЬНОГО КОНТАКТА С ВОДОЙ\nДлительное пребывание кожи, особенно стоп, в загрязнённой воде вызывает мацерацию (размягчение и повреждение кожи), повышающую риск инфицирования — по возможности необходима смена мокрой обуви и одежды на сухую как можно раньше.\n\nПИТЬЕВАЯ ВОДА И ПИЩА ПОСЛЕ НАВОДНЕНИЯ\nУпотребление только гарантированно чистой питьевой воды (бутилированной или прокипячённой), отказ от продуктов, контактировавших с паводковой водой, даже в закрытой упаковке при её повреждении — типичный источник вторичных пищевых отравлений после стихийных бедствий.\n\nПСИХОЛОГИЧЕСКОЕ СОСТОЯНИЕ ПОСЛЕ ПОТЕРИ ЖИЛЬЯ И ИМУЩЕСТВА\nНаводнение часто сопровождается потерей дома и имущества — состояние острого стресса, растерянности требует спокойной поддержки, практической помощи в организации быта и, при выраженных признаках, направления к специалистам психологической помощи, организованной в пунктах временного размещения.\n\nОРГАНИЗОВАННОЕ ВЗАИМОДЕЙСТВИЕ СО СЛУЖБАМИ ПОСЛЕ БЕДСТВИЯ\nРегистрация в пунктах временного размещения (упрощает розыск разлучённых членов семьи и получение помощи), содействие в предоставлении информации спасательным и медицинским службам о состоянии здоровья эвакуированных, особенно хронических заболеваний, требующих постоянных медикаментов.\n\nТИПИЧНЫЕ ОШИБКИ\nНедооценка риска инфицирования ран, контактировавших с паводковой водой; употребление воды или пищи сомнительного происхождения после бедствия; игнорирование психологического состояния пострадавших, потерявших жильё; отказ от регистрации в пунктах временного размещения.\n\nПРОВЕРЬ СЕБЯ\n1. Какие задачи возникают сразу после завершения эвакуации из зоны затопления?\n2. Почему раны, контактировавшие с паводковой водой, требуют особого внимания?\n3. Как правильно организовать питьевой и пищевой режим после наводнения?\n4. Как поддержать человека, потерявшего жильё и имущество при наводнении?\n5. Зачем нужна регистрация в пунктах временного размещения?'],
['Поведение во время подземных толчков','АКТУАЛЬНОСТЬ ТЕМЫ ДЛЯ РЕГИОНА\nКазахстан, включая Алматы, расположен в сейсмоопасной зоне — этот раздел курса имеет прямое практическое значение, а не только общеобразовательную ценность, что отличает его от части других тем курса, посвящённых менее вероятным для региона бедствиям.\n\nОСНОВНОЙ ПРИНЦИП: "УПАСТЬ, УКРЫТЬСЯ, ДЕРЖАТЬСЯ"\nМеждународно принятый алгоритм (drop, cover, hold on), рекомендованный сейсмологическими службами: немедленно упасть на четвереньки (снижает риск падения от толчков), укрыться под прочным столом или у внутренней несущей стены, держаться за укрытие до окончания толчков.\n\nПОЧЕМУ НЕ СЛЕДУЕТ БЕЖАТЬ К ВЫХОДУ ВО ВРЕМЯ ТОЛЧКОВ\nОсновная причина травм при землетрясениях — не обрушение зданий целиком (относительно редкое событие для большинства построек), а падающие предметы и попытки людей передвигаться во время толчков, приводящие к падениям и травмам — устаревшее представление о необходимости немедленно выбежать на улицу опровергнуто современными исследованиями сейсмобезопасности.\n\nБЕЗОПАСНЫЕ И ОПАСНЫЕ МЕСТА В ПОМЕЩЕНИИ\nБезопасно — под прочным столом, у внутренней капитальной стены, в дверном проёме несущей стены (в современных зданиях менее эффективно, чем считалось ранее, но всё ещё используется при отсутствии стола); опасно — рядом с окнами, зеркалами, тяжёлой мебелью и навесными полками, способными упасть.\n\nЕСЛИ ЗЕМЛЕТРЯСЕНИЕ ЗАСТАЛО НА УЛИЦЕ ИЛИ В АВТОМОБИЛЕ\nНа улице — отойти от зданий, линий электропередач и деревьев на открытое пространство; в автомобиле — остановиться в стороне от зданий, мостов и эстакад, оставаться внутри до окончания толчков, поскольку автомобиль обеспечивает определённую защиту от падающих обломков.\n\nДЕЙСТВИЯ СРАЗУ ПОСЛЕ ОКОНЧАНИЯ ТОЛЧКОВ\nПроверить себя и окружающих на травмы, оценить обстановку прежде чем двигаться (возможны повреждения конструкции, битое стекло, утечка газа по запаху), быть готовым к повторным толчкам (афтершокам), которые могут произойти в течение минут или часов после основного.\n\nТИПИЧНЫЕ ОШИБКИ\nПопытка выбежать из здания во время толчков вместо укрытия на месте; нахождение рядом с окнами или тяжёлой мебелью во время толчков; выход из автомобиля на открытой местности во время толчков; недооценка риска повторных толчков сразу после основного.\n\nПРОВЕРЬ СЕБЯ\n1. Почему тема землетрясений особенно актуальна для данного региона?\n2. Опишите алгоритм "упасть, укрыться, держаться".\n3. Почему не следует пытаться выбежать из здания во время толчков?\n4. Какие места в помещении безопасны, а какие опасны при землетрясении?\n5. Что нужно делать сразу после окончания подземных толчков?'],
['Краш-синдром при длительном сдавлении','ЧТО ТАКОЕ КРАШ-СИНДРОМ\nСиндром длительного сдавления (краш-синдром) развивается, когда часть тела (чаще конечность) находится под тяжёлым обломком продолжительное время — в сдавленных тканях накапливаются токсичные продукты распада мышц, которые при высвобождении конечности массово попадают в кровоток и способны вызвать острую почечную недостаточность и остановку сердца.\n\nПОЧЕМУ ЭТА ТЕМА КРИТИЧЕСКИ ВАЖНА ИМЕННО ПРИ ЗЕМЛЕТРЯСЕНИЯХ\nКраш-синдром — одна из ведущих причин смерти пострадавших, извлечённых из-под завалов, уже после, казалось бы, успешного спасения — правильные действия в момент освобождения конечности напрямую определяют выживание, что делает эту тему одной из важнейших в разделе о землетрясениях.\n\nГЛАВНОЕ ПРАВИЛО: НЕ ОСВОБОЖДАТЬ КОНЕЧНОСТЬ РЕЗКО САМОСТОЯТЕЛЬНО\nЕсли человек находится под завалом более 15-20 минут, немедленное освобождение конечности без медицинской подготовки способно резко ухудшить его состояние — по возможности необходимо дождаться прибытия медиков, которые проведут инфузионную терапию до освобождения сдавленной части тела.\n\nЕСЛИ ОСВОБОЖДЕНИЕ НЕИЗБЕЖНО БЕЗ МЕДИКОВ\nПри отсутствии возможности дождаться профессиональной помощи (непосредственная угроза жизни, например, продолжающийся пожар) — наложение жгута выше места сдавления непосредственно перед освобождением конечности, что временно ограничивает попадание токсичных веществ в общий кровоток.\n\nПРИЗНАКИ РАЗВИВАЮЩЕГОСЯ КРАШ-СИНДРОМА\nТёмная моча (признак повреждения мышечной ткани), отёк освобождённой конечности, признаки нарастающего шокового состояния через некоторое время после освобождения — при появлении любого из этих признаков необходима немедленная медицинская помощь.\n\nНАБЛЮДЕНИЕ ПОСЛЕ ОСВОБОЖДЕНИЯ\nДаже при кажущемся удовлетворительном состоянии сразу после извлечения — обязательное медицинское наблюдение в течение как минимум суток, поскольку симптомы краш-синдрома способны развиваться постепенно, а не проявляться немедленно.\n\nТИПИЧНЫЕ ОШИБКИ\nНемедленное самостоятельное освобождение длительно сдавленной конечности без учёта риска краш-синдрома; отказ от вызова скорой при кажущемся хорошем состоянии сразу после освобождения; непонимание необходимости жгута перед освобождением в экстренных случаях.\n\nПРОВЕРЬ СЕБЯ\n1. Что такое краш-синдром и чем он опасен?\n2. Почему нельзя резко освобождать длительно сдавленную конечность самостоятельно?\n3. Что делать, если освобождение неизбежно без медицинской помощи?\n4. Какие признаки указывают на развитие краш-синдрома?\n5. Почему необходимо наблюдение даже при хорошем состоянии сразу после освобождения?'],
['Извлечение пострадавших из-под завалов','ОЦЕНКА БЕЗОПАСНОСТИ ПЕРЕД НАЧАЛОМ ИЗВЛЕЧЕНИЯ\nПрежде чем приступать к извлечению пострадавшего, необходимо оценить устойчивость завала — попытки разбирать обломки без понимания их структуры способны вызвать дополнительное обрушение и создать ещё одну жертву, включая самого спасателя.\n\nПОИСК И КОММУНИКАЦИЯ С ПОСТРАДАВШИМ\nПериодические паузы тишины для прослушивания звуков (стуки, голоса) — стандартная практика поисково-спасательных операций; при обнаружении пострадавшего — голосовой контакт для оценки его состояния и поддержания психологического состояния до полного извлечения.\n\nПРИНЦИП АККУРАТНОГО, А НЕ БЫСТРОГО ИЗВЛЕЧЕНИЯ\nРазбор завала производится постепенно, слой за слоем, с оценкой устойчивости каждого убираемого элемента — поспешные действия ради скорости повышают риск дополнительного обрушения на пострадавшего или спасателя.\n\nПОДДЕРЖКА ПОСТРАДАВШЕГО ДО ПОЛНОГО ОСВОБОЖДЕНИЯ\nЕсли есть возможность частичного доступа (рука, лицо) до полного разбора завала — передача воды при сохранённом сознании и глотании, эмоциональная поддержка, контроль состояния сознания, но без попыток резко тянуть или двигать пострадавшего до оценки характера травм и сдавления.\n\nСВЯЗЬ С ТЕМОЙ КРАШ-СИНДРОМА\nМомент полного освобождения из-под завала — именно тот критический момент, когда должны применяться принципы, изложенные в теме краш-синдрома: оценка длительности сдавления, необходимость жгута при определённых условиях, недопустимость резкого освобождения при долгом сдавлении конечности.\n\nКОГДА ИЗВЛЕЧЕНИЕ ЛУЧШЕ ОСТАВИТЬ СПЕЦИАЛИСТАМ\nПри сложной структуре завала (многоэтажное разрушение, тяжёлые бетонные конструкции), при отсутствии необходимого инструмента и достаточного числа людей — безопаснее поддерживать контакт с пострадавшим и дожидаться специализированных спасательных служб с профессиональным оборудованием.\n\nТИПИЧНЫЕ ОШИБКИ\nБыстрый, неаккуратный разбор завала без оценки его устойчивости; резкое вытягивание пострадавшего до оценки характера травм; попытки самостоятельного извлечения из сложного завала при доступности профессиональных спасателей; отсутствие голосового контакта с пострадавшим во время извлечения.\n\nПРОВЕРЬ СЕБЯ\n1. Что нужно оценить перед началом извлечения пострадавшего из-под завала?\n2. Как поддерживать коммуникацию с пострадавшим при поиске?\n3. Почему извлечение должно быть аккуратным, а не быстрым?\n4. Как принципы краш-синдрома применяются в момент полного освобождения?\n5. Когда извлечение из-под завала лучше оставить профессиональным спасателям?'],
['Помощь после землетрясения и повторные толчки','ОПАСНОСТЬ АФТЕРШОКОВ\nПовторные толчки (афтершоки) способны происходить в течение часов, дней и даже недель после основного землетрясения — здания, повреждённые основным толчком, но устоявшие, могут обрушиться при менее сильном афтершоке, что делает возвращение в повреждённые здания крайне рискованным.\n\nОЦЕНКА БЕЗОПАСНОСТИ ЗДАНИЯ ПЕРЕД ВОЗВРАЩЕНИЕМ\nВидимые трещины в несущих стенах, перекос дверных и оконных проёмов, запах газа, повреждённая электропроводка — при любом из этих признаков возвращение в здание откладывается до осмотра специалистами, даже если внешне здание кажется устоявшим.\n\nОРГАНИЗАЦИЯ ВРЕМЕННОГО ПРЕБЫВАНИЯ НА ОТКРЫТОМ ПРОСТРАНСТВЕ\nПри значительных разрушениях в районе — временное размещение вдали от повреждённых зданий, линий электропередач и склонов, подверженных оползням после толчков; использование запасов воды и еды, подготовленных заблаговременно (если такая подготовка проводилась).\n\nОБЪЕДИНЕНИЕ РАНЕЕ ИЗУЧЕННЫХ ТЕМ КУРСА В КОНТЕКСТЕ ЗЕМЛЕТРЯСЕНИЯ\nПосле землетрясения часто одновременно актуальны темы кровотечений и травм (от обрушений и падающих предметов), краш-синдрома (у извлечённых из-под завалов), а иногда и пожаров (повреждённая проводка и газовые линии) — землетрясение иллюстрирует необходимость гибкого применения всего пройденного курса, а не одной изолированной темы.\n\nПРОВЕРКА КОММУНИКАЦИЙ ПОСЛЕ ТОЛЧКОВ\nПроверка (по возможности) утечек газа по запаху без использования открытого огня или электрических выключателей вблизи предполагаемой утечки, отключение повреждённой электропроводки, осторожность при использовании водопроводной воды до официального подтверждения её безопасности.\n\nПСИХОЛОГИЧЕСКОЕ СОСТОЯНИЕ И ДОЛГОСРОЧНОЕ ВОССТАНОВЛЕНИЕ\nТревога, связанная с ожиданием повторных толчков, естественна и обычно постепенно ослабевает — поддержка пострадавших простым присутствием, практической помощью и, при выраженных и стойких симптомах, обращением к специалистам психологической помощи, организованной службами экстренного реагирования.\n\nТИПИЧНЫЕ ОШИБКИ\nНемедленное возвращение в повреждённое здание без оценки его безопасности; использование открытого огня или электровыключателей при подозрении на утечку газа; недооценка риска афтершоков после основного толчка; игнорирование психологического состояния пострадавших после длительного стресса.\n\nПРОВЕРЬ СЕБЯ\n1. Почему афтершоки представляют самостоятельную опасность после основного землетрясения?\n2. По каким признакам можно заподозрить, что здание небезопасно для возвращения?\n3. Какие темы курса могут одновременно понадобиться после землетрясения?\n4. Как правильно проверять коммуникации (газ, электричество) после толчков?\n5. Как поддержать психологическое состояние пострадавших в ожидании повторных толчков?'],
['Подготовка и поведение при урагане','ПРЕДВАРИТЕЛЬНАЯ ПОДГОТОВКА ПРИ ПРОГНОЗИРУЕМОЙ УГРОЗЕ\nУраганы и тайфуны, в отличие от землетрясений, обычно прогнозируются заблаговременно (часы или дни) — это время используется для укрепления окон (щиты, скотч крест-накрест снижает разлёт осколков при разбитии, но не предотвращает его), уборки предметов с открытых балконов и дворов, которые способны стать летящими снарядами, и подготовки запаса воды, еды и заряженных устройств связи.\n\nВЫБОР МЕЖДУ ЭВАКУАЦИЕЙ И УКРЫТИЕМ НА МЕСТЕ\nРешение зависит от официальных рекомендаций служб гражданской обороны, прочности здания и предполагаемой силы урагана — при объявленной обязательной эвакуации она не игнорируется даже при кажущейся прочности собственного жилья, поскольку официальные решения опираются на данные, недоступные отдельному человеку.\n\nПОВЕДЕНИЕ ВНУТРИ ПОМЕЩЕНИЯ ВО ВРЕМЯ УРАГАНА\nНахождение в помещении без окон или с закрытыми ставнями (ванная, коридор, внутренняя кладовая), на самом низком уровне здания, не подверженном подтоплению, вдали от окон и дверей, способных быть выбитыми ветром.\n\nСАМАЯ ОПАСНАЯ ФАЗА: "ГЛАЗ" ЦИКЛОНА\nКратковременное затишье в центре урагана (глаз циклона) часто ошибочно принимается за окончание непогоды — выход наружу в этот момент опасен, поскольку после затишья ветер возобновляется с прежней или большей силой с противоположного направления.\n\nЧТО ДЕЛАТЬ СРАЗУ ПОСЛЕ ОСНОВНОЙ ФАЗЫ УРАГАНА\nОставаться внутри до официального объявления об окончании опасности, с осторожностью оценивать обстановку снаружи (поваленные провода под напряжением, повреждённые конструкции, скопления воды), не пользоваться повреждённой водопроводной водой без подтверждения её безопасности.\n\nСВЯЗЬ С ДРУГИМИ ТЕМАМИ КУРСА\nПосле урагана часто актуальны темы наводнения (штормовой нагон воды, ливневые паводки) и травм от обломков, рассматриваемых в следующей теме — стихийные бедствия редко изолированы друг от друга по своим последствиям.\n\nТИПИЧНЫЕ ОШИБКИ\nИгнорирование официальной рекомендации об эвакуации; выход наружу во время затишья в "глазу" циклона; нахождение рядом с окнами во время урагана; преждевременный выход из укрытия сразу после ослабления ветра.\n\nПРОВЕРЬ СЕБЯ\n1. Какие меры подготовки принимаются при заблаговременном прогнозе урагана?\n2. От чего зависит решение об эвакуации или укрытии на месте?\n3. Где безопаснее всего находиться внутри помещения во время урагана?\n4. Почему "глаз" циклона представляет скрытую опасность?\n5. Какие меры предосторожности нужны сразу после основной фазы урагана?'],
['Травмы от обломков и обрушений конструкций','ХАРАКТЕРНЫЙ МЕХАНИЗМ ТРАВМ ПРИ УРАГАНАХ\nВ отличие от землетрясений, где основная угроза — падение предметов внутри зданий, при ураганах преобладают травмы от летящих обломков (кровельные материалы, ветви деревьев, незакреплённые предметы), разлетающегося стекла и обрушения повреждённых ветром конструкций.\n\nПЕРВАЯ ПОМОЩЬ ПРИ ПРОНИКАЮЩИХ РАНЕНИЯХ ОТ ОБЛОМКОВ\nЕсли посторонний предмет застрял в ране — не извлекать его самостоятельно (может выполнять роль "пробки", ограничивающей кровотечение) — зафиксировать предмет в текущем положении подручными материалами и стабилизировать его от дальнейшего смещения при транспортировке, что напрямую перекликается с общими принципами первой помощи при ранах.\n\nСОЧЕТАННЫЕ ТРАВМЫ ПРИ ОБРУШЕНИИ КОНСТРУКЦИЙ\nКомбинация переломов, кровотечений и возможного длительного сдавления частей тела обломками конструкции — при подозрении на длительное сдавление применяются принципы темы краш-синдрома, изученной в разделе о землетрясениях, поскольку физиологический механизм травмы идентичен независимо от причины бедствия.\n\nОЦЕНКА БЕЗОПАСНОСТИ МЕСТА ОКАЗАНИЯ ПОМОЩИ\nПосле урагана территория часто остаётся опасной: оборванные провода под напряжением, неустойчивые повреждённые конструкции, продолжающийся, хотя и ослабевший, ветер — оценка безопасности себя и пострадавшего предшествует началу оказания помощи, в соответствии с общим принципом, изученным в самом начале курса.\n\nТРАВМЫ ОТ ПАДАЮЩИХ ДЕРЕВЬЕВ И ВЕТВЕЙ\nСпецифичный для ураганов источник травм — крупные ветви и целые деревья, поваленные ветром, способные причинить сочетанные травмы (перелом, сдавление, открытая рана) при падении на человека или транспортное средство, что требует комплексной оценки состояния пострадавшего по всем изученным ранее темам.\n\nОРГАНИЗАЦИЯ ПОМОЩИ ПРИ МНОЖЕСТВЕННЫХ ПОСТРАДАВШИХ\nКак и при пожаре, ураган способен одновременно травмировать несколько человек — применяется тот же принцип сортировки по срочности состояния (нарушение дыхания и сильное кровотечение в приоритете) при ограниченном количестве помощников.\n\nТИПИЧНЫЕ ОШИБКИ\nИзвлечение застрявшего в ране обломка самостоятельно; недооценка опасности территории после урагана (провода, неустойчивые конструкции) перед началом помощи; игнорирование признаков длительного сдавления при травмах от обрушенных конструкций.\n\nПРОВЕРЬ СЕБЯ\n1. Какой механизм травм характерен именно для ураганов, в отличие от землетрясений?\n2. Что делать, если посторонний предмет застрял в ране?\n3. Как принципы краш-синдрома применяются при обрушении конструкций во время урагана?\n4. Почему важно оценивать безопасность территории перед оказанием помощи после урагана?\n5. Как действовать при множественных пострадавших с ограниченным числом помощников?'],
['Поражение молнией','ОСОБЕННОСТИ ТРАВМЫ ОТ УДАРА МОЛНИИ\nПоражение молнией — разновидность тяжёлой электротравмы (см. тему электрических ожогов ранее в курсе) с рядом специфических черт: чрезвычайно высокое напряжение при крайне коротком времени воздействия, что нередко приводит к немедленной остановке сердца и дыхания, но также даёт шанс на успешную реанимацию при быстром начале помощи.\n\nБЕЗОПАСНОСТЬ СПАСАТЕЛЯ ПОСЛЕ УДАРА МОЛНИИ\nВ отличие от поражения электрическим током от проводки, тело пострадавшего после удара молнии не сохраняет заряд и не представляет опасности для оказывающего помощь — это отличие важно знать, чтобы не тратить время на излишние меры предосторожности, задерживающие начало реанимации.\n\nНЕМЕДЛЕННАЯ ОЦЕНКА И РЕАНИМАЦИЯ\nПри отсутствии дыхания и признаков кровообращения — немедленное начало сердечно-лёгочной реанимации по стандартному протоколу, изученному в модуле реанимации, поскольку при поражении молнией шансы на успешное восстановление сердечной деятельности выше, чем при многих других причинах остановки сердца, если помощь начата быстро.\n\nМНОЖЕСТВЕННЫЕ ПОСТРАДАВШИЕ И ПРИНЦИП "СНАЧАЛА БЕЗДЫХАННЫЕ"\nПри поражении молнией нескольких человек одновременно (например, группы на открытой местности) приоритет парадоксально отдаётся тем, кто выглядит наиболее тяжело пострадавшим (без дыхания и сознания), поскольку с высокой вероятностью выжившие после первого удара с сохранённым дыханием находятся в более стабильном состоянии — это отличается от обычной сортировки при массовых происшествиях.\n\nСОПУТСТВУЮЩИЕ ТРАВМЫ ПРИ УДАРЕ МОЛНИИ\nОжоги в точках входа и выхода тока (обычно менее выражены, чем при обычном электрическом ожоге), возможные переломы от резкого мышечного сокращения или падения в момент удара, временная потеря слуха или зрения — требуют оценки по соответствующим темам курса после стабилизации основного состояния.\n\nПРОДОЛЖАЮЩАЯСЯ ОПАСНОСТЬ ПОВТОРНОГО УДАРА\nЕсли гроза продолжается, место оказания помощи по возможности перемещается в более безопасное укрытие (низкое, вдали от отдельно стоящих деревьев и металлических предметов) — правило "30/30" (укрытие при интервале между молнией и громом менее 30 секунд, выход не ранее чем через 30 минут после последнего разряда) применимо и для самого спасателя.\n\nТИПИЧНЫЕ ОШИБКИ\nЗадержка начала реанимации из-за необоснованного страха "заряда" в теле пострадавшего; применение обычной сортировки по внешней тяжести состояния вместо принципа приоритета бездыханных при массовом поражении молнией; продолжение оказания помощи на открытом пространстве при продолжающейся грозе.\n\nПРОВЕРЬ СЕБЯ\n1. Чем поражение молнией отличается от обычной электротравмы по механизму?\n2. Безопасно ли прикасаться к пострадавшему сразу после удара молнии и почему?\n3. Почему шансы на успешную реанимацию при поражении молнией относительно высоки?\n4. В чём особенность сортировки при поражении молнией нескольких человек одновременно?\n5. Как учитывается продолжающаяся опасность повторного удара при оказании помощи?'],
['Сель, лавина и другие бедствия','АКТУАЛЬНОСТЬ ДЛЯ ГОРНОЙ МЕСТНОСТИ\nСели (грязекаменные потоки) и лавины особенно актуальны для регионов с горным рельефом, включая окрестности Алматы — это завершающая тема курса, объединяющая принципы, изученные в разделах о наводнениях и землетрясениях, применительно к специфике горных бедствий.\n\nСЕЛЬ: ПРИЗНАКИ И ПОВЕДЕНИЕ\nРезкое изменение уровня и цвета воды в горной реке, нарастающий гул — признаки приближающегося селя; при обнаружении этих признаков — немедленный подъём на возвышенность в стороне от русла реки, что аналогично принципу поведения при наводнении, но с более коротким временем на реакцию.\n\nЛАВИНА: ПОВЕДЕНИЕ ПРИ ПОПАДАНИИ В ЛАВИНУ\nПопытка выбраться к краю лавины энергичными плавательными движениями, при накрытии снегом — создание воздушного кармана перед лицом руками до полной остановки движения снега, что критически важно для последующего дыхания под снегом.\n\nПОИСК И ИЗВЛЕЧЕНИЕ ПОСТРАДАВШИХ ИЗ ЛАВИНЫ\nВремя критично: шансы на выживание резко падают после первых 15-20 минут под снегом из-за нехватки кислорода в воздушном кармане — по возможности использование лавинного датчика (бипера) для быстрого поиска, при его отсутствии — систематический осмотр видимой поверхности лавины и зондирование подручными предметами (лыжные палки).\n\nПЕРВАЯ ПОМОЩЬ ПОСЛЕ ИЗВЛЕЧЕНИЯ ИЗ ЛАВИНЫ\nОценка дыхания и признаков жизни как первостепенная задача, готовность к сердечно-лёгочной реанимации, учёт вероятного переохлаждения (см. тему обморожения и общего переохлаждения) и возможной травмы от удара о камни или деревья во время схода лавины.\n\nОБЩИЙ ПРИНЦИП КУРСА: ПЕРЕНОС ЗНАНИЙ МЕЖДУ РАЗДЕЛАМИ\nЭта завершающая тема специально демонстрирует, что стихийные бедствия используют один и тот же ограниченный набор физиологических механизмов травмы (кровотечение, перелом, переохлаждение, удушье, шок) — освоенные в предыдущих модулях навыки первой помощи применимы к любому новому виду бедствия, даже не описанному отдельно в программе.\n\nТИПИЧНЫЕ ОШИБКИ\nИгнорирование ранних признаков надвигающегося селя; попытки бороться с лавиной активными движениями всем телом вместо целенаправленных плавательных движений к краю; промедление с поиском попавших в лавину из-за недооценки критичности времени; недооценка сопутствующего переохлаждения после извлечения.\n\nПРОВЕРЬ СЕБЯ\n1. Почему тема селей и лавин особенно актуальна для данного региона?\n2. Какие признаки указывают на приближающийся сель и как действовать?\n3. Что нужно делать при попадании в лавину?\n4. Почему скорость поиска пострадавших в лавине критически важна?\n5. Какой общий принцип курса иллюстрирует эта завершающая тема?']
];
